import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IPageBbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageBbsComments";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of comments for a single post.
 *
 * This test covers the ability of the system to correctly return paginated, filtered lists of comments for a target post
 * using the /bbs/posts/{postId}/comments PATCH endpoint. It covers scenarios such as author filtering, date range filtering,
 * parent comment (thread/nesting) filtering, and edge cases (empty and invalid filters).
 *
 * Steps:
 * 1. Create a user.
 * 2. Create a post authored by that user.
 * 3. Add several comments to the post — at least 3 top-level and replies nesting at least 2 levels.
 * 4. List all comments without filters and verify all created comments are present.
 * 5. Filter comments by author_id and verify only that user’s comments are returned.
 * 6. Filter comments by parent_id for reply threading, verify only replies to a given parent are returned.
 * 7. Filter comments by date range (created_after, created_before) and verify the subset returned is correct.
 * 8. Use pagination (e.g. limit = 2, page = 2) and check paging metadata and data correctness.
 * 9. Check that deleted comments (if any) are NOT included.
 * 10. Test with filters that should return an empty set (e.g. non-existent author or parent) and confirm results are empty.
 * 11. Test with an invalid filter (e.g. nonsense UUIDs or impossible dates) and check API does not error or returns empty.
 */
export async function test_api_bbs_posts_comments_test_list_comments_for_post_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create a user (as author of posts/comments)
  // (Assume we have a valid role_id from the system; for end-to-end, this might be randomly generated or taken from fixture)
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongPassword123!",
      bio: "Test user for comment listing",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()()(2),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 3. Add several comments (3 top-level, 2 replies under 1st, 1 reply under a reply)
  const comments = [] as bbsComments[];
  for (let i = 0; i < 3; ++i) {
    const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: post.id,
      body: {
        content: `Top-level comment ${i+1}`,
      } satisfies bbsComments.ICreate,
    });
    typia.assert(comment);
    comments.push(comment);
  }
  // Add replies to the first top-level comment
  const reply1 = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Reply 1 to comment 1",
      parent_id: comments[0].id,
    } satisfies bbsComments.ICreate,
  });
  typia.assert(reply1);
  comments.push(reply1);
  const reply2 = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Reply 2 to comment 1",
      parent_id: comments[0].id,
    } satisfies bbsComments.ICreate,
  });
  typia.assert(reply2);
  comments.push(reply2);
  // Nested reply (reply to reply1)
  const nestedReply = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Nested reply to reply1",
      parent_id: reply1.id,
    } satisfies bbsComments.ICreate,
  });
  typia.assert(nestedReply);
  comments.push(nestedReply);

  // 4. List all comments without filters
  const listAll = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: {} satisfies bbsComments.IRequest,
  });
  typia.assert(listAll);
  const allIds = comments.map(c => c.id);
  for (const c of comments) {
    TestValidator.predicate("all created comments appear")(listAll.data.some(item => item.id === c.id));
  }

  // 5. Filter by author_id
  const listByAuthor = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { author_id: user.id } satisfies bbsComments.IRequest,
  });
  typia.assert(listByAuthor);
  TestValidator.predicate("all returned are by user")(listByAuthor.data.every(item => item.user_id === user.id));

  // 6. Filter by parent_id (should only return replies to first top-level comment)
  const listReplies = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { parent_id: comments[0].id } satisfies bbsComments.IRequest,
  } as any);
  typia.assert(listReplies);
  TestValidator.equals("replies to first comment")(2)(listReplies.data.length);
  TestValidator.predicate("all replies have correct parent_id")(listReplies.data.every(item => item.parent_id === comments[0].id));

  // 7. Filter by created_after / created_before (pick timestamps of one comment for edge checks)
  const afterDate = comments[0].created_at;
  const beforeDate = comments[comments.length - 1].created_at;
  const listAfter = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { created_after: afterDate } satisfies bbsComments.IRequest,
  });
  typia.assert(listAfter);
  TestValidator.predicate("all comments in listAfter are created after the specified date")(
    listAfter.data.every(item => item.created_at > afterDate),
  );
  const listBefore = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { created_before: beforeDate } satisfies bbsComments.IRequest,
  });
  typia.assert(listBefore);
  TestValidator.predicate("all comments in listBefore are created before the specified date")(
    listBefore.data.every(item => item.created_at < beforeDate),
  );

  // 8. Pagination check (limit=2, page=2)
  const paged = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: {
      limit: 2 as number & tags.Type<"int32">,
      page: 2 as number & tags.Type<"int32">,
    },
  });
  typia.assert(paged);
  TestValidator.equals("pagination, page number")(2)(paged.pagination.current);
  TestValidator.equals("pagination, limit")(2)(paged.pagination.limit);

  // 9. Deleted comments are not included — not implemented here due to lack of delete endpoint or DTO field in test, skip.

  // 10. Empty results: non-existent author
  const emptyByAuthor = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: {
      author_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(emptyByAuthor);
  TestValidator.equals("empty for unknown author")(0)(emptyByAuthor.data.length);
  // Non-existent parent
  const emptyByParent = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: {
      parent_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(emptyByParent);
  TestValidator.equals("empty for unknown parent")(0)(emptyByParent.data.length);

  // 11. Invalid filters (nonsense UUIDs or dates)
  // Here the system should not error — just return empty or error gracefully.
  await TestValidator.error("invalid author_id should not error fatally")(
    async () => {
      await api.functional.bbs.posts.comments.patchByPostid(connection, {
        postId: post.id,
        body: { author_id: "not-a-uuid" as any },
      });
    },
  );
  await TestValidator.error("invalid date range should not error fatally")(
    async () => {
      await api.functional.bbs.posts.comments.patchByPostid(connection, {
        postId: post.id,
        body: {
          created_after: "9999-99-99T99:99:99Z" as any,
        },
      });
    },
  );
}

