import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";

/**
 * Validates creating a top-level comment on a post in the BBS system.
 *
 * This test verifies:
 * 1. A registered user can successfully comment on an existing post with valid content.
 * 2. Input validation catches empty comment content.
 * 3. A 404 or equivalent error is thrown when commenting on a non-existent post.
 * 4. Guests (unauthenticated users) are forbidden from posting comments.
 *
 * Workflow:
 * 1. Register a user with a valid role ID, unique username/email, and password.
 * 2. Simulate authentication as that user (relies on connection token semantics).
 * 3. Create a new post authored by the user (valid random title/content/category_id).
 * 4. Add a valid top-level comment (non-empty `content`) and assert the returned result is as expected (content, user, post IDs, timestamps).
 * 5. Attempt to add a comment with empty or whitespace content (should fail validation).
 * 6. Attempt to comment on a random non-existent post ID (should fail with not found).
 * 7. Log out (clear auth header), then try to comment as a guest (should be forbidden).
 */
export async function test_api_bbs_test_create_comment_on_post_valid_and_invalid(connection: api.IConnection) {
  // 1. Register a user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(10) + '@example.com',
      password: 'Password123!',
      role_id: typia.random<string & tags.Format<'uuid'>>()
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(user);

  // 2. Create a post as the user
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<'uuid'>>(),
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()()()
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post);

  // 3. Create valid top-level comment
  const validContent = RandomGenerator.content()()();
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: validContent
    } satisfies bbsComments.ICreate
  });
  typia.assert(comment);
  TestValidator.equals('comment content')(validContent)(comment.content);
  TestValidator.equals('comment postId')(post.id)(comment.post_id);
  TestValidator.equals('comment parent should be null')(null)(comment.parent_id ?? null);

  // 4. Try to create a comment with empty content (should fail validation)
  await TestValidator.error('empty comment content should fail')(async () => {
    await api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: post.id,
      body: {
        content: ''
      } satisfies bbsComments.ICreate
    });
  });

  // 5. Try to create a comment on a non-existent post
  await TestValidator.error('comment on non-existent post should fail')(async () => {
    await api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: typia.random<string & tags.Format<'uuid'>>(),
      body: {
        content: RandomGenerator.content()()()
      } satisfies bbsComments.ICreate
    });
  });

  // 6. Try to comment when unauthenticated (simulate logout by clearing auth header if possible)
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers?.Authorization;
  await TestValidator.error('unauthenticated comment creation should fail')(async () => {
    await api.functional.bbs.posts.comments.postByPostid(unauthConn, {
      postId: post.id,
      body: {
        content: RandomGenerator.content()()()
      } satisfies bbsComments.ICreate
    });
  });
}

