 */
export async function putByPostidAndId(
  connection: IConnection,
  props: putByPostidAndId.Props,
): Promise<putByPostidAndId.Response> {
  return !!connection.simulate
    ? putByPostidAndId.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...putByPostidAndId.METADATA,
          path: putByPostidAndId.path(props),
          status: null,
        },
        props.body,
      );
}
export namespace putByPostidAndId {
  export type Props = {
    /** The post to which the comment belongs. */
    postId: string & tags.Format<"uuid">;

    /** The unique identifier of the comment to update. */
    id: string & tags.Format<"uuid">;

    /**
     * Updated values for the comment (e.g., new content, parentId for
     * re-threading).
     */
    body: bbsComments.IUpdate;
  };
  export type Body = bbsComments.IUpdate;
  export type Response = bbsComments;

  export const METADATA = {
    method: "PUT",
    path: "/bbs/posts/:postId/comments/:id",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Omit<Props, "body">) =>
    `/bbs/posts/${encodeURIComponent(props.postId ?? "null")}/comments/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): bbsComments =>
    typia.random<bbsComments>(g);
  export const simulate = (
    connection: IConnection,
    props: putByPostidAndId.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: putByPostidAndId.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("postId")(() => typia.assert(props.postId));
      assert.param("id")(() => typia.assert(props.id));
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

