 * comments table in the Prisma schema, including parent-child threading, audit,
 * and moderation soft-delete support.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type bbsComments = {
  /**
   * Unique identifier for the comment, `id` primary key from the comments
   * table.
   *
   * Used system-wide to reference comments in API operations and thread
   * navigation.
   */
  id: string & tags.Format<"uuid">;

  /**
   * UUID of the user who wrote this comment, matching `user_id` in comments
   * table.
   *
   * Used for author audits, reply tracking, and profile linking.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * UUID of the post this comment is attached to, from `post_id` in the
   * comments table.
   *
   * Critical for threading, structure, and navigation of discussion posts.
   */
  post_id: string & tags.Format<"uuid">;

  /**
   * If present, this is the UUID of the parent comment, enabling
   * threading/nesting of replies. Nullable for top-level comments.
   *
   * Implements self-referential comment hierarchy as explained in
   * requirements and Prisma schema.
   */
  parent_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Body/content of the comment, from the `content` field in comments table.
   *
   * Carries user opinion, replies, and substantive discussion.
   */
  content: string;

  /**
   * Timestamp for comment creation, from `created_at` column.
   *
   * Used in chronological sorting, audit, and moderation.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp for last update of the comment, as per `updated_at` field.
   *
   * Reflects edit history and moderation actions.
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * Soft deletion flag (if present) indicating when this comment was
   * 'deleted' for moderation, but not physically removed from the database.
   *
   * Null if currently active.
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;
};
export namespace bbsComments {
  /**
   * Model for creating a new comment on a post or as a reply to another
   * comment.
   *
   * Based on the requirements document and comments schema, this interface
   * allows users to create either a top-level comment or a nested reply. Only
   * registered users may comment. Thread assignment is supported via optional
   * parent_id.
   */
  export type ICreate = {
    /**
     * Comment body text.
     *
     * This property contains the text that will be displayed as the content
     * of the comment. It implements the rule that each comment consists of
     * user-written content. For example: 'I agree and here’s why...'.
     * Referenced from the 'content' column in the Prisma comments model and
     * per requirements in 03_data_structure_and_business_rules.md.
     */
    content: string;

    /**
     * The ID of the parent comment for nested/threaded replies. Nullable
     * for top-level comments (direct replies to posts).
     *
     * Referenced from 'parent_id' in the comments Prisma schema. Implements
     * thread/nesting support and conversation branching per requirements.
     */
    parent_id?: (string & tags.Format<"uuid">) | null;
  };

  /**
   * Model for updating an existing comment. Allows comment text to be edited
   * subject to audit and ownership rules (see Prisma comment model and
   * requirements analysis).
   */
  export type IUpdate = {
    /**
     * Updated comment body text.
     *
     * Changed content for this comment. Enforces non-empty value and
     * transparent audit trails, per the 'content' column in comments Prisma
     * model.
     */
    content: string;
  };
}

