 *
 * This test verifies the update of a BBS post comment by its author and enforces appropriate permissions and input validation. It also covers edge cases as far as possible with the available APIs.
 *
 * Scenario Steps:
 * 1. Create User A (author) and User B (non-author)
 * 2. Create a post (by User A)
 * 3. User A creates a comment on this post
 * 4. User A updates the comment's content, and updated_at changes
 * 5. User B attempts to update the comment, expecting a permission error (simulate as possible)
 * 6. Attempt to update the comment with empty content (should fail validation)
 * 7. Attempt to update a non-existent comment (should error)
 *
 * Note: Soft-deletion and true user session switching cannot be tested as no delete or auth switch API is available.
 */
export async function test_api_bbs_test_update_comment_content_owner_and_permission(connection: api.IConnection) {
  // 1. Create User A (author) and User B (non-author)
  const roleId: string = typia.random<string & tags.Format<"uuid">>();
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userA = await api.functional.bbs.users.post(connection, {
