    api.functional.bbs.posts.comments.putByPostidAndId(connection, {
      postId: post.id,
      id: comment.id,
      body: {
        content: "",
      } satisfies bbsComments.IUpdate,
    })
  );

  // 7. Update on non-existent comment (random UUID)
  TestValidator.error("update non-existent comment fails")(() =>
    api.functional.bbs.posts.comments.putByPostidAndId(connection, {
