import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";

/**
 * Test comment deletion (soft delete) by various actors: original author, moderator/administrator, and unrelated user. 
 * First, create users for each role and a post with a comment by the author. 
 * The author should be able to soft-delete their own comment, which sets the 'deleted_at' field. 
 * A moderator/administrator should also be able to delete the comment regardless of authorship. 
 * An unrelated user attempting deletion should receive a permission error. 
 * Confirm deletion is idempotent (trying to delete an already deleted comment returns an error or no-op). 
 * Attempt to delete a non-existent comment and verify correct error handling. 
 * Also check that a deleted comment cannot be interacted with by regular users.
 */
export async function test_api_bbs_test_delete_comment_by_author_moderator_and_unauthorized(connection: api.IConnection) {
  // 1. Create roles (in a real system, these should be present in the database):
  // For testing, assume we know the UUIDs for role: member, moderator, admin (these are needed for user creation)
  // Here we mock such values – in production would fetch from roles API or pre-seed them
  const memberRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const adminRoleId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Create users: author, moderator, unrelated user
  // Author (member)
  const authorUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass123!",
      bio: "Author of the comment",
      role_id: memberRoleId,
    }
  });
  typia.assert(authorUser);

  // Moderator
  const moderatorUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass456!",
      bio: "Moderator user",
      role_id: moderatorRoleId,
    }
  });
  typia.assert(moderatorUser);

  // Unrelated user
  const unrelatedUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass789!",
      bio: "Unrelated user",
      role_id: memberRoleId,
    }
  });
  typia.assert(unrelatedUser);

  // 3. Create a post as author
  // (Assume system determines current user from authentication – not exposed via API, so in tests, simulate/authenticate as author)
  // For E2E: Imagine connection.headers.Authorization is swapped before each role-sensitive API call
  // Here, we simulate this via comment
  // Authenticate as author
  // connection.headers.Authorization = ... (author's credentials)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test Post for Comment Deletion Scenarios",
      content: "This post is for testing comment deletion workflows.",
    },
  });
  typia.assert(post);

  // 4. Author creates a comment on the post
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "This is a comment that will be targeted for deletion.",
    },
  });
  typia.assert(comment);

  // 5. Attempt to delete comment as the author (should succeed, sets deleted_at)
  await api.functional.bbs.posts.comments.eraseByPostidAndId(connection, {
    postId: post.id,
    id: comment.id,
  });
  // After deletion: fetch comment again (if possible) or assert deleted_at changed if comment is returned.
  // This API suite doesn't expose get comment, so this can't be validated directly here. (Would need a comment fetch/list API.)

  // 6. Attempt idempotent delete as the author (should fail or be a no-op – check for error)
  await TestValidator.error("Deleting an already deleted comment returns error or no-op")(
    () => api.functional.bbs.posts.comments.eraseByPostidAndId(connection, {
      postId: post.id,
      id: comment.id,
    })
  );

  // 7. Attempt to delete as unrelated user (should fail with permission error)
  // connection.headers.Authorization = ... (unrelated user)
  await TestValidator.error("Unrelated user cannot delete comment")(
    () => api.functional.bbs.posts.comments.eraseByPostidAndId(connection, {
      postId: post.id,
      id: comment.id,
    })
  );

  // 8. Attempt to delete as moderator (should also be accepted, even if already deleted – or trigger idempotent error)
  // connection.headers.Authorization = ... (moderator user)
  await TestValidator.error("Moderator deleting already deleted comment is error/no-op")(
    () => api.functional.bbs.posts.comments.eraseByPostidAndId(connection, {
      postId: post.id,
      id: comment.id,
    })
  );

  // 9. Attempt to delete a non-existent comment – should return not found/appropriate error
  await TestValidator.error("Deleting non-existent comment fails")(
    () => api.functional.bbs.posts.comments.eraseByPostidAndId(connection, {
      postId: post.id,
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 10. Try to interact with the deleted comment as a regular user (impossible here, but would test fetch/list endpoints if present)
  // Since API doesn't expose fetch-specific comment method, skip this validation here.
}

