/**
 * Validate listing and paginated retrieval of discussion categories with search/filter functionality.
 *
 * Ensures that when several categories with different names and descriptions are present in the system, the listing endpoint (PATCH /bbs/categories)
 * correctly returns filtered and paginated results according to search keywords, filters (by name, description), and pagination controls (page, limit).
 * The test simulates an admin creating several categories and then performs multiple queries to verify that:
 * - Search by name / description returns correct categories.
 * - Pagination (page, limit) works and boundaries are respected.
 * - Result metadata (IPage.IPagination) correctly reflects completeness.
 * - Every listed record contains all necessary fields (id, name, description, created_at).
 *
 * Steps:
 * 1. Create several categories with distinct names and descriptions.
 * 2. Query for all categories, ensure all are present, and check correct pagination (all on one page by default, correct total, etc).
 * 3. Query with `limit` lower than number of categories, check returned count and pagination (should be multi-page).
 * 4. Query for search keywords that match only certain categories (by name, by description).
 * 5. Test pagination with `page` and `limit` to fetch specific pages, ensure correct contents per page.
 * 6. For each queried item, check required fields are present and of correct type.
 */
export async function test_api_bbs_test_list_categories_with_valid_pagination_and_filters(connection: api.IConnection) {
  // Step 1: Create several categories with unique names and descriptions
  const categories = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const category = await api.functional.bbs.categories.post(connection, {
      body: {
        name: `TestCategory_${RandomGenerator.alphabets(6)}_${i}`,
        description: `Description_${RandomGenerator.alphabets(8)}_${i}`,
      },
    });
    typia.assert(category);
    return category;
  });

  // Step 2: Query all categories (no filter)
  let pageAll = await api.functional.bbs.categories.patch(connection, {
    body: {}
  });
  typia.assert(pageAll);
  TestValidator.predicate("total categories >= test data")(pageAll.pagination.records >= categories.length);
  TestValidator.equals("category fields present")(true)(pageAll.data.every(cat => cat.id && cat.name && cat.description && cat.created_at));

  // Step 3: Query with limit lower than number of categories
