import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";

/**
 * Test successful retrieval of a single BBS category's details by UUID.
 *
 * Scenario & Purpose:
 * - Ensures that after creating a new discussion category (using POST /bbs/categories), the details
 *   can be retrieved via GET /bbs/categories/{id} with a valid UUID.
 * - Verifies essential fields: name, description, and created_at are correctly set and returned.
 * - This reflects a core part of category selection or category detail viewing in the UI.
 *
 * Steps:
 * 1. Create a new category using a unique name and description (POST /bbs/categories).
 * 2. Retrieve this category by its UUID using GET /bbs/categories/{id}.
 * 3. Assert the returned details (name, description, created_at) match the originally created category.
 * 4. Assert id matches, and the created_at is a valid date-time string.
 */
export async function test_api_bbs_categories_getById_successful(
  connection: api.IConnection,
) {
  // 1. Create a new category for lookup
  const input: bbsCategories.ICreate = {
    name: `E2E-Test-${RandomGenerator.alphaNumeric(8)}`,
    description: `Test category created for test_api_bbs_categories_getById_successful. ${RandomGenerator.paragraph()(1)}`,
  };
  const created = await api.functional.bbs.categories.post(connection, { body: input });
  typia.assert(created);

  // 2. Retrieve that category by ID
  const result = await api.functional.bbs.categories.getById(connection, { id: created.id });
  typia.assert(result);

  // 3. Assert the returned fields match
  TestValidator.equals("category id matches")(created.id)(result.id);
  TestValidator.equals("category name matches")(created.name)(result.name);
  TestValidator.equals("category description matches")(created.description)(result.description);

  // 4. Check created_at validity and that it is non-empty
  TestValidator.predicate("created_at is valid date-time")(
    !!result.created_at && !Number.isNaN(Date.parse(result.created_at))
  );
}

