import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";

/**
 * Validate the creation of a new BBS category with valid data by an administrator.
 *
 * This test verifies the category management functionality, ensuring that an admin can create a new discussion category (e.g., Politics, Economics) with unique, non-empty name and description. This covers the happy path scenario, confirming that valid category data results in successful creation—allowing the new category to be referenced for listing and associating posts.
 *
 * Steps:
 * 1. Prepare valid, unique 'name' and 'description' for category creation.
 * 2. Call the category creation API as an authenticated admin.
 * 3. Assert that the response contains a valid new category with matching name and description, and proper UUID and timestamp formats.
 * 4. (Optional, if practical in available API) Validate that the system can subsequently reference the new category for post assignment or listing (if a listing API were available).
 */
export async function test_api_bbs_test_create_category_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare valid and unique category data
  const categoryName = `${RandomGenerator.alphabets(8)}_${typia.random<number & tags.Type<"uint32">>()}`;
  const categoryDescription = RandomGenerator.paragraph()(1);

  // 2. Call the API to create the new category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: categoryName,
      description: categoryDescription,
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Assert that the output values match the input and required formats
  TestValidator.equals("name matches input")(categoryName)(category.name);
  TestValidator.equals("description matches input")(categoryDescription)(category.description);

  if (!category.id || typeof category.id !== "string" || !category.id.match(/[0-9a-fA-F-]{36}/)) {
    throw new Error("Returned category.id is not a valid UUID string");
  }
  if (!category.created_at || typeof category.created_at !== "string" || isNaN(Date.parse(category.created_at))) {
    throw new Error("Returned category.created_at is not a valid datetime string");
  }
}

