  typia.assert(updated);

  // Step 3: Assert the update response matches expected, and id stays the same
  TestValidator.equals("Category ID remains unchanged")(category.id)(updated.id);
  TestValidator.equals("Updated name set")(updatedName)(updated.name);
  TestValidator.equals("Updated description set")(updatedDescription)(updated.description);
}

