import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";

/**
 * 카테고리 이름 중복 업데이트 유효성 검사 E2E 테스트.
 *
 * 이 테스트는 관리자가 기존에 존재하는 카테고리 이름으로 또 다른 카테고리의 이름을 변경하려 할 때 서버가 고유성 제약 위반(uniqueness error)을 적절히 반환하는지 검증합니다.
 *
 * 1. admin 자격으로 첫 번째 카테고리A를 생성한다 (고유한 name 및 description 사용)
 * 2. admin 자격으로 두 번째 카테고리B를 생성한다 (서로 다른 name, description 사용)
 * 3. 두 번째 카테고리B를, 첫 번째 카테고리A와 동일한 이름으로 업데이트를 시도한다
 * 4. 서버가 중복 이름 에러를 반환하는지 TestValidator.error()로 검증한다
 *
 * - name, description 모두 schema 요구사항(비어있지 않고, name은 전체 카테고리에서 유일해야 함)을 반드시 지켜야 함.
 */
export async function test_api_bbs_test_update_category_with_duplicate_name(
  connection: api.IConnection,
) {
  // 1. 카테고리A 생성
  const categoryAInput = {
    name: `E2E-중복이름테스트-${RandomGenerator.alphaNumeric(8)}`,
    description: `카테고리A 설명: ${RandomGenerator.paragraph()(1)}`,
  } satisfies bbsCategories.ICreate;
  const categoryA = await api.functional.bbs.categories.post(connection, {
    body: categoryAInput,
  });
  typia.assert(categoryA);

  // 2. 카테고리B 생성
  const categoryBInput = {
    name: `E2E-중복이름테스트-${RandomGenerator.alphaNumeric(8)}`,
    description: `카테고리B 설명: ${RandomGenerator.paragraph()(1)}`,
  } satisfies bbsCategories.ICreate;
  const categoryB = await api.functional.bbs.categories.post(connection, {
    body: categoryBInput,
  });
  typia.assert(categoryB);

  // 3. 카테고리B의 이름을, categoryA와 동일하게 변경 시도
  const updateInput = {
    name: categoryA.name,
    description: `중복이름 업데이트 시도: ${RandomGenerator.paragraph()(1)}`,
  } satisfies bbsCategories.IUpdate;

  // 4. 서버가 중복 이름 에러를 반환하는지 TestValidator.error로 검증
  await TestValidator.error("중복 이름 업데이트는 실패해야 한다")(() =>
    api.functional.bbs.categories.putById(connection, {
      id: categoryB.id,
      body: updateInput,
    })
  );
}

