import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate that deleting a category with dependent posts is not allowed.
 *
 * This test ensures the BBS API enforces referential integrity by preventing the deletion of a category if it is still referenced by existing posts. Admins are required to reassign or handle those posts before the category can be deleted.
 *
 * Steps:
 * 1. Create a unique BBS category
 * 2. Create a user account
 * 3. Create a post under that category as the new user
 * 4. Attempt to delete the category while the post exists—this should fail
 * 5. Validate that the deletion fails with a dependency/conflict error
 */
export async function test_api_bbs_test_delete_category_with_dependent_posts(
  connection: api.IConnection,
) {
  // 1. Create a new discussion category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 2. Create a role for the user if not already required/available (skip—no role creation API)
  // Pick a random role UUID for now or mock a valid one
  const randomRoleId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create a user account
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      role_id: randomRoleId,
      bio: RandomGenerator.paragraph()(10),
    },
  });
  typia.assert(user);

  // 4. Create a post in the new category as the created user (simulate user context if required)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 5. Attempt to delete the category while it is referenced
  await TestValidator.error("Should not delete category with dependent posts")(
    async () => {
      await api.functional.bbs.categories.eraseById(connection, { id: category.id });
    },
  );
}

