import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { bbsCategories } from "../../../structures/bbsCategories";

/**
 * Delete a category by ID (BBS: categories table).
 *
 * This API endpoint allows an authenticated administrator to delete a
 * discussion category by its ID from the BBS system. It removes the specified
 * record from the 'categories' table. Prior to deletion, the system checks for
 * posts referencing this category; administrators may need to reassign or
 * handle these posts to maintain board integrity.
 *
 * Only users with appropriate administrator roles (as defined in the
 * 'user_roles' table) are permitted to invoke this operation. Attempts to
 * delete a category with dependent posts may result in an error until those
 * dependencies are resolved. On successful completion, the category is
 * permanently removed from the database; deleted category names can be reused
 * when creating new categories.
 *
 * Related endpoints include creating, updating, and listing categories.
 *
 * @param props.connection
 * @param props.id The identifier of the category to delete.
 * @path /bbs/categories/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function eraseById(
  connection: IConnection,
  props: eraseById.Props,
): Promise<eraseById.Response> {
  return !!connection.simulate
    ? eraseById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...eraseById.METADATA,
          path: eraseById.path(props),
          status: null,
        },
      );
}
export namespace eraseById {
  export type Props = {
    /** The identifier of the category to delete. */
    id: string & tags.Format<"uuid">;
  };
  export type Response = bbsCategories;

  export const METADATA = {
    method: "DELETE",
    path: "/bbs/categories/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/bbs/categories/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): bbsCategories =>
    typia.random<bbsCategories>(g);
  export const simulate = (
    connection: IConnection,
    props: eraseById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: eraseById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

