/**
 * Validate that attempting to delete a category with a non-existent UUID results in a robust error.
 *
 * This test confirms that the API returns an appropriate error when trying to delete a phantom resource (a category ID that does not exist in the system). It ensures the deletion route is safe from ghost deletions and gives clear feedback to clients.
 *
 * Test Steps:
 * 1. Generate a random UUID that is extremely unlikely to exist in the database (for test isolation and low collision probability).
 * 2. Attempt to delete the category using this non-existent UUID via the eraseById endpoint.
 * 3. Verify that the API throws an error (e.g., 404 Not Found or similar business logic error) and does NOT return a successful response.
 * 4. Validate that the error handling is consistent and robust (using TestValidator.error).
 */
export async function test_api_bbs_test_delete_category_with_nonexistent_id(connection: api.IConnection) {
  const nonExistentId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Deleting non-existent category should throw error")(async () => {
    await api.functional.bbs.categories.eraseById(connection, { id: nonExistentId });
  });
}

