import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate retrieval of user role details by a valid UUID.
 *
 * This test covers the end-to-end flow for reading a user role's metadata:
 * 1. Create a new user role with a unique name and description.
 * 2. Call GET /bbs/userRoles/{id} using the UUID returned from creation step.
 * 3. Assert that the fetched role's id, name, and description perfectly match the original creation payload.
 * 4. Ensure the returned entity contains no extraneous user information—only metadata fields (id, name, description) must be present.
 */
export async function test_api_bbs_userRoles_getById(connection: api.IConnection) {
  // 1. Create a new user role
  const createPayload: IBbsUserRoles.ICreate = {
    name: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(1),
  };
  const created: IBbsUserRoles = await api.functional.bbs.userRoles.post(
    connection,
    { body: createPayload }
  );
  typia.assert(created);

  // 2. Retrieve the role by UUID
  const fetched: IBbsUserRoles = await api.functional.bbs.userRoles.getById(
    connection,
    { id: created.id },
  );
  typia.assert(fetched);

  // 3. Validate all fields match
  TestValidator.equals("id matches")(createPayload.name)(fetched.name);
  TestValidator.equals("description matches")(createPayload.description)(fetched.description);
  TestValidator.equals("id matches")(created.id)(fetched.id);

  // 4. Ensure only expected properties are present
  const allowedKeys = ["id", "name", "description"];
  const fetchedKeys = Object.keys(fetched);
  if (fetchedKeys.some((k) => !allowedKeys.includes(k))) {
    throw new Error(`Response contains extra properties: ${fetchedKeys.filter((k) => !allowedKeys.includes(k)).join(", ")}`);
  }
}

