import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate creation of user roles with invalid payloads.
 *
 * This test verifies that the API endpoint for creating user roles correctly rejects invalid input data and does not create partial or erroneous records. Proper validation handling is essential for platform security and data integrity, as user roles define system governance and permissions. The test covers various invalid payloads, including missing required fields, empty strings, and malformed data.
 *
 * Steps:
 * 1. Attempt to create a role without the 'name' field.
 * 2. Attempt to create a role without the 'description' field.
 * 3. Attempt to create a role with both fields empty strings.
 * 4. Attempt to create a role with either field as an empty string.
 * 5. Attempt to create a role with malformed data types (number instead of string).
 * 6. After each failure, verify that no invalid record has been created (API should reject, no valid response object should be returned).
 */
export async function test_api_bbs_test_create_user_role_with_invalid_payload(
  connection: api.IConnection,
) {
  // 1. Attempt to create a role missing 'name'
  await TestValidator.error("missing 'name' fails")(() =>
    api.functional.bbs.userRoles.post(connection, {
      body: {
        // name is missing
        description: "A test role without a name."
      } as any,
    }),
  );

  // 2. Attempt to create a role missing 'description'
  await TestValidator.error("missing 'description' fails")(() =>
    api.functional.bbs.userRoles.post(connection, {
      body: {
        name: "testRoleWithoutDescription",
        // description is missing
      } as any,
    }),
  );

  // 3. Attempt to create a role with both fields as empty strings
  await TestValidator.error("both fields empty strings fail")(() =>
    api.functional.bbs.userRoles.post(connection, {
      body: {
        name: "",
        description: "",
      } satisfies IBbsUserRoles.ICreate,
    }),
  );

  // 4a. Attempt with empty-string name
  await TestValidator.error("empty string name fails")(() =>
    api.functional.bbs.userRoles.post(connection, {
      body: {
        name: "",
        description: "Valid description",
      } satisfies IBbsUserRoles.ICreate,
    }),
  );

  // 4b. Attempt with empty-string description
  await TestValidator.error("empty string description fails")(() =>
    api.functional.bbs.userRoles.post(connection, {
      body: {
        name: "validRoleName",
        description: "",
      } satisfies IBbsUserRoles.ICreate,
    }),
  );

  // 5a. Malformed: number for name
  await TestValidator.error("number as name fails")(() =>
    api.functional.bbs.userRoles.post(connection, {
      body: {
        name: 123 as any,
        description: "description text",
      },
    }),
  );

  // 5b. Malformed: number for description
  await TestValidator.error("number as description fails")(() =>
    api.functional.bbs.userRoles.post(connection, {
      body: {
        name: "validRoleName",
        description: 456 as any,
      },
    }),
  );
}

