/**
 * Test deleting a user role with an invalid or non-existent UUID.
 *
 * This test covers the deletion endpoint for user roles, specifically for failure cases when the provided ID is either malformed (not a UUID) or references a user role that does not exist. The objective is to confirm that:
 *
 * 1. The API rejects clearly malformed UUID inputs with a validation error.
 * 2. The API returns a not-found or similar error when a well-formed but non-existent UUID is provided.
 * 3. No unrelated user roles are affected by an invalid delete request.
 *
 * Step-by-step process:
 * 1. Attempt to delete a user role using a malformed ID that is not a UUID - expect a validation error.
 * 2. Attempt to delete a user role using a valid UUID that does not correspond to any existing role - expect a not-found error.
 * 3. (Optional, if possible) Query or list roles before and after to verify none were inadvertently deleted.
 */
export async function test_api_bbs_userRoles_test_delete_user_role_with_invalid_id(
  connection: api.IConnection,
) {
  // 1. Try deleting with a malformed UUID
  await TestValidator.error("malformed role UUID should fail")(() =>
    api.functional.bbs.userRoles.eraseById(connection, {
      id: "not-a-uuid" as string & tags.Format<"uuid">,
    }),
  );

  // 2. Try deleting with a non-existent but valid UUID
  await TestValidator.error("non-existent role UUID should fail")(() =>
    api.functional.bbs.userRoles.eraseById(connection, {
      id: "e89b2e88-f99b-476c-b525-2e8bfcb85b29" as string & tags.Format<"uuid">,
    }),
  );

  // 3. (Schema/SDK doesn’t provide a list endpoint, so skip verifying remaining roles)
}

