import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that user role deletion requires proper authentication and privileges.
 *
 * This test ensures that only authorized users can delete a user role. It verifies that:
 *
 * 1. An unauthenticated user (no token) cannot delete a user role (should fail)
 * 2. An authenticated user lacking proper privileges cannot delete a user role (should fail)
 *
 * The tests expect authorization errors to be thrown for both cases.
 *
 * Step-by-step:
 * 1. Create a user role to target for deletion
 * 2. Attempt user role deletion with unauthenticated connection (no auth headers)
 * 3. (Skipped: Attempt with authenticated user lacking privileges - not feasible with current SDK functions)
 * 4. Validate that unauthorized attempts fail with authorization errors
 */
export async function test_api_bbs_test_delete_user_role_requires_authorization(connection: api.IConnection) {
  // 1. Create a user role as setup
  const createdRole = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(createdRole);

  // 2. Attempt deletion as UNAUTHENTICATED user
  const unauthenticatedConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated should not delete user role")(() =>
    api.functional.bbs.userRoles.eraseById(unauthenticatedConnection, {
      id: createdRole.id,
    })
  );

  // 3. (Skipped: No means to simulate insufficient privileges with current SDK/API)
  // If the SDK/API provided user role switching or privilege restriction simulation, we would attempt deletion as a restricted user.
  // This step is omitted due to API constraints.
}

