  const categories = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<'uuid'>>());
  const posts = await ArrayUtil.asyncRepeat(2)(async (_, i) => {
    const post = await api.functional.bbs.posts.post(connection, {
      body: {
        category_id: categories[i],
        title: `Test Post ${i + 1}`,
        content: `Content for post ${i + 1}`,
      } satisfies bbsPosts.ICreate,
    });
    typia.assert(post);
    return post;
  });

  // Step 4: Create comments
  const comments = await ArrayUtil.asyncRepeat(2)(async (i) => {
    const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: posts[i].id,
      body: {
        content: `Comment ${i + 1}`,
      } satisfies bbsComments.ICreate,
    });
    typia.assert(comment);
    return comment;
  });

  // Step 5: Cast votes
  // Log in as user1 and user2
  const [user1, user2] = users;
  // Assume bearer info is handled by connection, simulate direct voting
  // (user1 votes +1 on post1, -1 on comment1)
  let vote1 = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: posts[0].id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote1);
  let vote2 = await api.functional.bbs.votes.post(connection, {
    body: {
      comment_id: comments[0].id,
      value: -1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote2);
  // (user2 votes -1 on post2, +1 on comment2)
  let vote3 = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: posts[1].id,
      value: -1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote3);
  let vote4 = await api.functional.bbs.votes.post(connection, {
    body: {
      comment_id: comments[1].id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote4);

  // Step 6: List votes - no filter
  const allVotes = await api.functional.bbs.votes.patch(connection, {
    body: {} satisfies IBbsVote.IRequest,
  });
  typia.assert(allVotes);
  TestValidator.predicate('all votes returned')(allVotes.data.length >= 4);

  // Step 7: Filter by user_id
  const user1Votes = await api.functional.bbs.votes.patch(connection, {
    body: { user_id: user1.id } satisfies IBbsVote.IRequest,
  });
  typia.assert(user1Votes);
  TestValidator.predicate('user1 votes filtered')(user1Votes.data.every(v => v.user_id === user1.id));

  // Step 8: Filter by post_id
  const post1Votes = await api.functional.bbs.votes.patch(connection, {
    body: { post_id: posts[0].id } satisfies IBbsVote.IRequest,
  });
  typia.assert(post1Votes);
  TestValidator.predicate('post1 votes filtered')(post1Votes.data.every(v => v.post_id === posts[0].id));

  // Step 9: Filter by comment_id
  const comment1Votes = await api.functional.bbs.votes.patch(connection, {
    body: { comment_id: comments[0].id } satisfies IBbsVote.IRequest,
  });
  typia.assert(comment1Votes);
  TestValidator.predicate('comment1 votes filtered')(comment1Votes.data.every(v => v.comment_id === comments[0].id));

  // Step 10: Filter by value
  const posVotes = await api.functional.bbs.votes.patch(connection, { body: { value: 1 } satisfies IBbsVote.IRequest });
  typia.assert(posVotes);
  TestValidator.predicate('only positive votes')(posVotes.data.every(v => v.value === 1));
  const negVotes = await api.functional.bbs.votes.patch(connection, { body: { value: -1 } satisfies IBbsVote.IRequest });
  typia.assert(negVotes);
  TestValidator.predicate('only negative votes')(negVotes.data.every(v => v.value === -1));

  // Step 11: Pagination
  // Limit to 2, fetch page 1
  const pagedVotes1 = await api.functional.bbs.votes.patch(connection, {
    body: { limit: 2, page: 1 } satisfies IBbsVote.IRequest,
  });
  typia.assert(pagedVotes1);
  TestValidator.equals('page 1')(pagedVotes1.pagination.current)(1);
  TestValidator.predicate('page 1 count')(pagedVotes1.data.length <= 2);

  // If there are more than 2 votes, page 2 should exist
  if (allVotes.data.length > 2) {
    const pagedVotes2 = await api.functional.bbs.votes.patch(connection, {
      body: { limit: 2, page: 2 } satisfies IBbsVote.IRequest,
    });
    typia.assert(pagedVotes2);
    TestValidator.equals('page 2')(pagedVotes2.pagination.current)(2);
  }

  // Step 12: Paginating past the end
  const outOfBounds = await api.functional.bbs.votes.patch(connection, {
    body: { limit: 2, page: 100 } satisfies IBbsVote.IRequest,
  });
  typia.assert(outOfBounds);
  TestValidator.equals('empty page')(outOfBounds.data.length)(0);

  // Step 13: Combination filter: user1 votes, value +1
  const comboFiltered = await api.functional.bbs.votes.patch(connection, {
    body: { user_id: user1.id, value: 1 } satisfies IBbsVote.IRequest,
  });
  typia.assert(comboFiltered);
  TestValidator.predicate('user1 +1 votes')(comboFiltered.data.every(v => v.user_id === user1.id && v.value === 1));

  // Step 14: Zero results (invalid user_id)
  const noneResults = await api.functional.bbs.votes.patch(connection, {
    body: { user_id: typia.random<string & tags.Format<'uuid'>>() } satisfies IBbsVote.IRequest,
  });
  typia.assert(noneResults);
  TestValidator.equals('no votes with random user')(noneResults.data.length)(0);

  // Step 15: Invalid filter (unsupported value)
  await TestValidator.error('invalid value filter')(async () => {
    await api.functional.bbs.votes.patch(connection, {
      body: { value: 0 } as any,
    });
  });
}

