import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate vote detail access control and error handling.
 *
 * This test ensures that access to a vote record by its ID is restricted to the
 * vote owner or privileged users (admins), and yields errors otherwise. It covers:
 * 1. Verifying that a non-owner, non-admin cannot access vote details (expecting forbidden/denied error)
 * 2. Verifying that an unauthenticated/guest user cannot access vote details
 * 3. Verifying that fetching a completely nonexistent vote ID returns not-found error
 *
 * Steps:
 * 1. CREATE A VOTE (as user A via dependency)
 * 2. Attempt GET of the vote detail as another user (user B). Should fail.
 * 3. Attempt GET as unauthenticated/guest. Should fail.
 * 4. Attempt GET using a fake random vote UUID (nonexistent). Should fail with not found.
 * The test validates proper role checks and existence checks for secure vote record access.
 */
export async function test_api_bbs_test_get_vote_detail_unauthorized_or_not_found(connection: api.IConnection) {
  // Step 1: Create a vote as User A (dependency)
  // Auth steps implied (User A must be signed in)
  const vote: IBbsVote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(), // Simulate vote on post
      value: 1 as const
    } satisfies IBbsVote.ICreate
  });
  typia.assert(vote);

  // Step 2: Try getting the vote detail as another user (User B)
  // Simulate login as a different user (User B)
  // This assumes a test infra where connection can swap user context
  await TestHelpers.authenticateAsDifferentUser(connection);
  await TestValidator.error("Non-owner, non-admin cannot access vote")(
    async () => {
      await api.functional.bbs.votes.getById(connection, { id: vote.id });
    },
  );

  // Step 3: Try getting the vote as guest/unauthenticated
  await TestHelpers.deauthenticate(connection);
  await TestValidator.error("Guest cannot access vote by ID")(
    async () => {
      await api.functional.bbs.votes.getById(connection, { id: vote.id });
    },
  );

  // Step 4: Try getting a non-existent vote
  const fakeId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Not found for random non-existent vote id")(
    async () => {
      await api.functional.bbs.votes.getById(connection, { id: fakeId });
    },
  );
}

