import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Test the successful creation of a vote for a post, ensuring uniqueness and association.
 *
 * This scenario covers the workflow for a regular user to upvote or downvote a post, covering both success and business rule enforcement:
 *
 * 1. Register a new regular user (requires role assignment);
 * 2. Create a post (with valid random category assignment);
 * 3. User creates a vote (+1 or -1) for the post;
 * 4. Validate the returned vote response object: must reference the post, user, and valid value;
 * 5. Attempt to create a duplicate vote for the same post and user, and confirm failure (unique constraint enforcement).
 */
export async function test_api_bbs_test_create_vote_on_post_with_valid_data(connection: api.IConnection) {
  // 1. Register a new regular user (mock role assignment)
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      bio: RandomGenerator.paragraph()(),
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(user);

  // 2. Create a post (requires a category_id, which must be a UUID)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()(1)(),
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post);

  // 3. User votes (+1 or -1)
  const voteValue = RandomGenerator.pick([-1, 1]);
  const vote = await api.functional.bbs.votes.post(connection, {
    body: { post_id: post.id, comment_id: null, value: voteValue } satisfies IBbsVote.ICreate
  });
  typia.assert(vote);
  TestValidator.equals("voter id")(user.id)(vote.user_id);
  TestValidator.equals("related post")(post.id)(vote.post_id);
  TestValidator.equals("vote value")(voteValue)(vote.value);
  TestValidator.equals("comment_id should be null")(null)(vote.comment_id);

  // 4. Duplicate vote attempt (same user & post)
  await TestValidator.error("should fail duplicate vote creation")(() =>
    api.functional.bbs.votes.post(connection, {
      body: { post_id: post.id, comment_id: null, value: voteValue } satisfies IBbsVote.ICreate
    })
  );
}

