import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validates prevention of duplicate votes on the same target (post or comment) by the same user.
 *
 * This test ensures a user is allowed to cast only a single vote per entity (either post or comment). It covers:
 *   1. Creating and registering a user (with a real role_id)
 *   2. Creating a post (which will be the voting target)
 *   3. Casting a vote (upvote) on the post as the user (should succeed)
 *   4. Attempting to cast a second vote (on the same post) by the same user (should fail with business rule error)
 *   5. [If comment functionality is available: Repeat same kind of check for a comment attached to the post.]
 *
 * It validates the business requirement that users may cast only one vote per entity and enforces database or application-level uniqueness.
 */
export async function test_api_bbs_test_create_vote_duplicate_on_same_target_fails(connection: api.IConnection) {
  // Step 1: Register a test user with random username and email, real role_id required
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const userInput: IBbsUsers.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongP@ssw0rd" + RandomGenerator.alphaNumeric(4),
    bio: RandomGenerator.paragraph()(1),
    role_id: userRoleId,
  };
  const user = await api.functional.bbs.users.post(connection, { body: userInput });
  typia.assert(user);

  // Step 2: Create a post that the user will vote on
  const postInput: bbsPosts.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    content: RandomGenerator.content()()(),
  };
  const post = await api.functional.bbs.posts.post(connection, { body: postInput });
  typia.assert(post);

  // Step 3: First vote should succeed
  const voteCreate: IBbsVote.ICreate = {
    post_id: post.id,
    value: 1,
  };
  const vote = await api.functional.bbs.votes.post(connection, { body: voteCreate });
  typia.assert(vote);

  // Step 4: Second (duplicate) vote attempt should fail
  await TestValidator.error("duplicate vote on post should fail")(() =>
    api.functional.bbs.votes.post(connection, { body: voteCreate })
  );

  // Optionally, you may repeat same logic for a comment if comment voting is implemented
}

