import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate that unauthenticated users cannot vote.
 *
 * This test ensures a guest user (missing bearer token) cannot create a vote on a post.
 * This enforces the authentication requirements and permissions barrier for voting.
 *
 * Steps:
 * 1. Create a post (as an authenticated user, dependency setup)
 * 2. Attempt to create a vote as an unauthenticated/guest user (no auth headers in connection)
 *     - Use the post's id
 *     - Expect an error due to missing authentication
 */
export async function test_api_bbs_test_create_vote_unauthorized_user_fails(
  connection: api.IConnection,
) {
  // 1. Setup: Create a post to serve as a valid voting target (simulate authenticated user)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test Post for Unauthorized Vote",
      content: "This post is used to test unauthenticated voting.",
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 2. Attempt to create a vote as a guest (unauthenticated connection)
  //    - Clone the base connection but strip headers to simulate no auth
  const guestConnection = { ...connection, headers: {} };
  TestValidator.error("guest user cannot vote")(() =>
    api.functional.bbs.votes.post(guestConnection, {
      body: {
        post_id: post.id,
        value: 1,
      } satisfies IBbsVote.ICreate,
    })
  );
}

