import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Test that creating a vote with an invalid or nonexistent post/comment ID returns an error.
 *
 * This test ensures the voting API enforces correct target validation, rejecting attempts to create votes for nonexistent or deleted posts/comments. The API should respond with an error when passed an invalid UUID as post_id or comment_id (e.g., a random UUID not associated with any post or comment in the database).
 *
 * Workflow:
 * 1. Create a valid user (dependency, to authorize the API call if required).
 * 2. Attempt to create a vote with a random UUID as the post_id (no such post exists).
 *    - The vote should not be created and the API must respond with a not-found error or equivalent.
 * 3. Attempt to create a vote with a random UUID as the comment_id (no such comment exists).
 *    - The vote should not be created and the API must respond with a not-found error or equivalent.
 *
 * Both cases verify the server correctly checks target existence and does not allow orphaned votes. This prevents data inconsistencies and ensures robust input validation at the API level.
 */
export async function test_api_bbs_test_create_vote_with_invalid_target_returns_error(
  connection: api.IConnection,
) {
  // 1. Register a valid user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(8) + "@test.com",
      password: "StrongP@ssw0rd!",
      // role_id: must be a valid UUID - for a real test, supply a valid role from your DB or test fixtures
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: null,
    },
  });
  typia.assert(user);

  // 2. Try to vote using a nonexistent post_id (random uuid)
  await TestValidator.error("voting for non-existent post should fail")(async () => {
    await api.functional.bbs.votes.post(connection, {
      body: {
        post_id: typia.random<string & tags.Format<"uuid">>(),
        comment_id: null,
        value: 1,
      },
    });
  });

  // 3. Try to vote using a nonexistent comment_id (random uuid)
  await TestValidator.error("voting for non-existent comment should fail")(async () => {
    await api.functional.bbs.votes.post(connection, {
      body: {
        post_id: null,
        comment_id: typia.random<string & tags.Format<"uuid">>(),
        value: -1,
      },
    });
  });
}

