import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Test updating a vote value as the owner (voter).
 *
 * This test covers the workflow for a user who votes on a post and later changes (updates) that vote's value. Business rules require one vote per target per user, and only the owner (voter) can update their vote. Tallies (post upvote/downvote counts) should reflect the update.
 *
 * Workflow:
 * 1. Create a user to act as voter. (Requires random username, email, password, role_id.)
 * 2. Create a post (user must be authenticated). Requires valid category_id, title, content.
 *    - Note: no category API provided, so must generate a random UUID for category_id.
 * 3. As the user, cast an upvote (+1) for the new post.
 * 4. Update the vote (using vote id) to change value to -1 (downvote).
 * 5. Validate that the returned vote record value is updated and references are correct.
 * 6. (If possible: Validate that tallies for the post change accordingly, but no tally API exposed, so can only check the vote entity).
 */
export async function test_api_bbs_test_update_vote_value_successful_as_owner(connection: api.IConnection) {
  // 1. Create a user
  const role_id = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphaNumeric(12);
  const email = `${RandomGenerator.alphaNumeric(6)}@example.com`;
  const password = RandomGenerator.alphaNumeric(16);
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      role_id,
      bio: RandomGenerator.paragraph()(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a post (as the user)
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 3. Vote (+1) on the post
  const vote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("vote value is +1")(1)(vote.value);

  // 4. Update vote value to -1
  const updatedVote = await api.functional.bbs.votes.putById(connection, {
    id: vote.id,
    body: {
      value: -1,
    } satisfies IBbsVote.IUpdate,
  });
  typia.assert(updatedVote);

  // 5. Validate that updatedVote.value is -1 and references remain unchanged
  TestValidator.equals("vote value updated to -1")(-1)(updatedVote.value);
  TestValidator.equals("vote still references correct user")(vote.user_id)(updatedVote.user_id);
  TestValidator.equals("vote still references same post")(vote.post_id)(updatedVote.post_id);

  // 6. (No tally validation possible as no read/tally endpoint exists)
}

