import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate update vote access control for owner, guest, and moderator roles.
 *
 * This test scenario ensures only the vote owner (authenticated) and privileged users (like moderators)
 * can update an existing vote record, while non-owner normal users and guests cannot. It also confirms
 * proper error responses for insufficient permissions and that allowed users succeed.
 *
 * Step-by-step process:
 * 1. Register a normal user (as vote owner)
 * 2. Register another normal user (non-owner)
 * 3. Register a moderator user
 * 4. Authenticate as the owner, create a post, then cast a vote (record owner)
 * 5. Authenticate as the non-owner user, attempt to update the owner's vote (expect error)
 * 6. Authenticate as the moderator user, attempt to update the owner's vote (expect success)
 * 7. Logout (simulate guest), attempt to update the owner's vote (expect error)
 * 8. Authenticate as the owner, update their own vote (expect success)
 */
export async function test_api_bbs_test_update_vote_as_non_owner_or_unauthorized_fails(
  connection: api.IConnection,
) {
  // 1. Register vote owner user (normal role)
  const ownerRoleId: string = /* UUID for normal user role */ typia.random<string & tags.Format<"uuid">>();
  const owner: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd!",
      bio: null,
      role_id: ownerRoleId,
    },
  });
  typia.assert(owner);

  // 2. Register another normal/non-owner user
  const nonOwnerRoleId: string = /* UUID for normal user role */ typia.random<string & tags.Format<"uuid">>();
  const nonOwner: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd!",
      bio: null,
      role_id: nonOwnerRoleId,
    },
  });
  typia.assert(nonOwner);

  // 3. Register moderator user
  const moderatorRoleId: string = /* moderator role UUID; must have elevated permissions */ typia.random<string & tags.Format<"uuid">>();
  const moderator: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd!",
      bio: null,
      role_id: moderatorRoleId,
    },
  });
  typia.assert(moderator);

  // 4. Authenticate as owner, create post, cast vote
  // (Assuming authentication mechanism sets proper access for the connection)
  // (No direct login SDK — assume role simulation, or token manipulation handled externally)
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);
  const vote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    },
  });
  typia.assert(vote);

  // 5. Authenticate as non-owner (simulate, adjust token), attempt update
  // (Assuming connection context can swap to nonOwner user)
  TestValidator.error("Non-owner should not update owner's vote")(() =>
    api.functional.bbs.votes.putById(connection, {
      id: vote.id,
      body: { value: -1 },
    })
  );

  // 6. Authenticate as moderator, attempt update
  // (Assuming connection context is now moderator)
  let moderatorUpdatedVote: IBbsVote | undefined;
  try {
    moderatorUpdatedVote = await api.functional.bbs.votes.putById(connection, {
      id: vote.id,
      body: { value: -1 },
    });
    typia.assert(moderatorUpdatedVote);
  } catch {
    throw new Error("Moderator should be able to update any vote");
  }

  // 7. Logout/guest: attempt update
  // (Simulate guest/no-auth connection)
  TestValidator.error("Guest should not update owner's vote")(() =>
    api.functional.bbs.votes.putById(connection, {
      id: vote.id,
      body: { value: 1 },
    })
  );

  // 8. Authenticate as owner again, update own vote
  let ownerUpdatedVote: IBbsVote | undefined;
  try {
    ownerUpdatedVote = await api.functional.bbs.votes.putById(connection, {
      id: vote.id,
      body: { value: -1 },
    });
    typia.assert(ownerUpdatedVote);
    TestValidator.equals("Vote is updated by owner")(-1)(ownerUpdatedVote.value);
  } catch {
    throw new Error("Owner should be able to update their own vote");
  }
}

