 * 6. As moderator: attempt to update the owner's vote (expect success)
 * 7. As guest: attempt to update the owner's vote (expect error)
 * 8. As owner: update own vote (expect success)
 */
export async function test_api_bbs_test_update_vote_as_non_owner_or_unauthorized_fails(
  connection: api.IConnection,
) {
  // 1. Register vote owner (normal user)
  const ownerRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const owner: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd!",
      bio: null,
      role_id: ownerRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(owner);

  // 2. Register another normal user (non-owner)
  const nonOwnerRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const nonOwner: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd!",
      bio: null,
      role_id: nonOwnerRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(nonOwner);

  // 3. Register moderator
  const moderatorRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const moderator: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "P@ssw0rd!",
      bio: null,
      role_id: moderatorRoleId,
