  // Step 2: Prepare a valid update payload (vote value +1)
  const updatePayload = {
    value: 1,
  } satisfies IBbsVote.IUpdate;

  // Step 3: Attempt to update the vote with nonexistent ID
  await TestValidator.error("Nonexistent vote update should fail")(
    () =>
