import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * 테스트 목적: 투표의 소유자(작성자)와 관리자가 해당 투표를 성공적으로 삭제할 수 있음을 검증한다. 
 *
 * 비즈니스 시나리오:
 * 1. 일반 사용자와 관리자(ROLE: admin) 2명을 회원가입 시킨다.
 * 2. 테스트용 게시글을 여러개 생성하여 각기 투표 타겟으로 쓴다.
 * 3. 일반 사용자가 게시글 1에 투표를 만든다(예: upvote).
 * 4. 본인(일반 사용자) 계정으로 해당 투표(vote)를 삭제한다. 성공적으로 삭제되어야 하며, 삭제 후 재투표가 가능함을 검증한다.
 * 5. 두 번째 게시글(post2)에 대해 투표를 만든다(다른 투표값 가능).
 * 6. 이번에는 관리자 계정으로 두 번째 투표를 삭제한다. 마찬가지로 성공적으로 삭제되며, 해당 대상(post2)에 다시 투표가 가능한지 확인한다.
 * 
 * 검증 포인트:
 * - 투표 삭제 후 다시 투표가 가능한지(중복방지 비즈니스 로직 정상 동작 확인)
 * - 삭제는 소유자와 어드민만 가능(본 테스트에서는 소유자/어드민 성공 케이스 검증).
 * - 투표 삭제 API 성공 결과 (204/no-content OK)
 */
export async function test_api_bbs_test_delete_vote_successful_by_owner_and_admin(
  connection: api.IConnection,
) {
  // 1. 역할별 계정 생성 (일반/관리자)
  const memberRoleId = typia.random<string & tags.Format<"uuid">>();
  const adminRoleId = typia.random<string & tags.Format<"uuid">>();

  const normalUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234test",
      role_id: memberRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(normalUser);

  const adminUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password: "admin1pass",
      role_id: adminRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(adminUser);

  // 2. 투표 타겟용 게시글 2개 생성
  const post1 = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(10),
      content: RandomGenerator.paragraph()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post1);

  const post2 = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(8),
      content: RandomGenerator.paragraph()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post2);

  // 3. (일반)사용자 투표 생성 - 게시글1
  // [실제 서비스는 인증 토큰 발급, 여기서는 connection user context 전환 생략함]
  const vote1 = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post1.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote1);

  // 4. 본인 계정(일반 사용자)으로 투표 삭제
  await api.functional.bbs.votes.eraseById(connection, { id: vote1.id });

  // 4-1. 동일 게시글에 재투표 가능 확인
  const vote1Again = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post1.id,
      value: -1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote1Again);
  TestValidator.equals("vote1 재투표 post_id 동일성")(vote1.post_id)(vote1Again.post_id);
  TestValidator.equals("vote1 재투표 user 동일성")(vote1.user_id)(vote1Again.user_id);

  // 5. 게시글2 대상 또 다른 투표 생성
  const vote2 = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post2.id,
      value: -1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote2);

  // 6. 관리자 계정으로 투표 삭제 (connection 내 admin user context 전환 직전 로그인 가정)
  // 실제 서비스라면 인증전환이 필요, 본 테스트에선 동일 connection 사용
  await api.functional.bbs.votes.eraseById(connection, { id: vote2.id });

  // 6-1. 동일 대상에 다시 투표 가능 확인
  const vote2Again = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post2.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote2Again);
  TestValidator.equals("vote2 재투표 post_id 동일성")(vote2.post_id)(vote2Again.post_id);
  TestValidator.equals("vote2 재투표 user 동일성")(vote2.user_id)(vote2Again.user_id);
}

