 *
 * This test ensures API-level access control for destructive actions: only the vote's owner or users with privileged roles (e.g., moderator, admin) may delete a vote.
 *
 * Workflow:
 * 1. Register two regular users: the Vote Creator and the Attacker (non-owner, unprivileged)
 * 2. The Vote Creator creates a post
 * 3. The Vote Creator votes on the post (generates a vote record)
 * 4. Switch authentication to the Attacker
 * 5. Attempt to delete the vote belonging to the Vote Creator
 * 6. Verify that deletion attempt fails (API returns forbidden/unauthorized error)
 * 7. (Optionally) Confirm the vote record still exists in the system
 *
 * This test validates essential RBAC: only the vote owner (or a privileged user) can delete their vote. The Attacker, lacking such privileges, should be denied. This prevents malicious or abusive vote manipulation by third parties.
 */
export async function test_api_bbs_test_delete_vote_as_non_owner_fails(connection: api.IConnection) {
  // 1. Register the Vote Creator
  const creatorRoleId = typia.random<string & tags.Format<"uuid">>();
  const creatorEmail = typia.random<string & tags.Format<"email">>();
