 *
 * This test ensures that the posts listing endpoint supports complex queries combining filtering, sorting, and pagination. The flow covers full business requirements, including user and category setup, multiple post creation across categories, and end-to-end validation of filter/sort/pagination functionality.
 *
 * Steps:
 * 1. Create new user for posting (with unique role_id, fake but valid format)
 * 2. Create two distinct categories
 * 3. Create posts under BOTH categories, some in each
 * 4. List posts filtering by the first category, sorted by creation date descending, with a pagination limit (e.g. 2)
 * 5. Validate:
 *    - Only posts in that category are returned
 *    - Sorting by creation date is correct (newest first)
 *    - Pagination reports correct page, limit, and total count
 *    - Changing page returns next results
 */
export async function test_api_bbs_test_list_posts_with_valid_filters_and_pagination(connection: api.IConnection) {
