import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IPageBbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageBbsPosts";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that the post listing API gracefully handles invalid query parameters and rejects unsupported requests with appropriate validation errors.
 *
 * This test ensures that attempts to use out-of-range pagination (such as negative or zero limits), invalid filter keys, or non-existent category IDs do not result in leaks of database records and that error responses are handled correctly. A valid user is registered for authentication.
 *
 * Step-by-step process:
 * 1. Register a valid user.
 * 2. Attempt to list posts with a negative limit and/or invalid pagination (expect validation error, no records leaked).
 * 3. Attempt to list posts with an obviously non-existent category_id (random UUID that doesn't exist) (expect error, no records leaked).
 * 4. Attempt to include a field that doesn't exist in the filter (should result in validation error).
 * 5. Verify for each: that a HttpError or error object is received and no valid records are returned.
 */
export async function test_api_bbs_test_list_posts_invalid_parameters(connection: api.IConnection) {
  // 1. Register a valid user for authentication.
  const roleId: string = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Validpassw0rd!",
      role_id: roleId,
      bio: null,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Attempt to list posts with a negative limit on pagination (invalid parameter)
  await TestValidator.error("Negative limit for pagination should throw validation error")(() =>
    api.functional.bbs.posts.patch(connection, {
      body: {
        limit: -10,
        page: 1,
      } satisfies bbsPosts.IRequest,
    })
  );

  // 3. Attempt to list posts with a non-existent category_id
  await TestValidator.error("Non-existent category_id should throw validation error")(() =>
    api.functional.bbs.posts.patch(connection, {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies bbsPosts.IRequest,
    })
  );

  // 4. Attempt to include an invalid field in filter (should cause validation error)
  // bbsPosts.IRequest does not allow extra properties, so this cannot even be constructed in TS (TypeScript will error).
  // Thus, we will document that this case cannot be implemented in TS and is skipped.
}

