import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * 게시글 상세 조회 성공 시나리오를 검증합니다.
 *
 * 이 테스트는 게시글의 생성부터 상세 조회까지의 핵심 플로우를 다룹니다.
 * 필수 정보의 정확성과 누락 없는 반환을 확인하는 것이 목적입니다.
 *
 * 1. 게시글 저자가 될 유저 계정을 생성합니다.
 * 2. 게시글의 카테고리로 사용할 분류(Category)를 생성합니다.
 * 3. 생성된 유저와 카테고리로 게시글을 작성합니다.
 * 4. 해당 게시글의 id로 상세정보 조회를 요청합니다.
 * 5. 조회 결과의 title, content, user_id, category_id, 타임스탬프(created_at/updated_at), 삭제여부(deleted_at) 등 모든 필수 필드가 올바르게 반환되는지 검증합니다.
 */
export async function test_api_bbs_test_get_post_by_id_success(
  connection: api.IConnection,
) {
  // 1. 게시글 저자가 될 유저 생성
  const userRoleId = typia.random<string & tags.Format<'uuid'>>();
  const username = RandomGenerator.alphaNumeric(8);
  const email = `${RandomGenerator.alphaNumeric(7)}@example.com`;
  const password = RandomGenerator.alphaNumeric(12);
  const bio = RandomGenerator.alphabets(15);
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      bio,
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. 카테고리 생성
  const categoryName = RandomGenerator.alphabets(8);
  const categoryDescription = RandomGenerator.paragraph()();
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: categoryName,
      description: categoryDescription,
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. 게시글 생성
  const postTitle = RandomGenerator.paragraph()();
  const postContent = RandomGenerator.content()()();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      content: postContent,
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. 생성된 게시글을 id로 상세 조회
  const fetched = await api.functional.bbs.posts.getById(connection, {
    id: post.id,
  });
  typia.assert(fetched);

  // 5. 상세 조회 결과의 필수 필드 및 값 정합성 검증
  TestValidator.equals('제목')(postTitle)(fetched.title);
  TestValidator.equals('내용')(postContent)(fetched.content);
  TestValidator.equals('작성자')(user.id)(fetched.user_id);
  TestValidator.equals('카테고리')(category.id)(fetched.category_id);
  TestValidator.equals('생성일')(post.created_at)(fetched.created_at);
  TestValidator.equals('수정일')(post.updated_at)(fetched.updated_at);
  // deleted_at은 기본적으로 null이거나 undefined이어야 함 (생성 게시글은 삭제된 적이 없으므로)
  TestValidator.predicate('삭제여부 - 미삭제')(fetched.deleted_at === null || typeof fetched.deleted_at === "undefined");
  // 필수 필드 누락 여부 검사 (타입 검증과 별도 논리)
  [
    fetched.id,
    fetched.user_id,
    fetched.category_id,
    fetched.title,
    fetched.content,
    fetched.created_at,
    fetched.updated_at,
  ].forEach((field, idx) => {
    if (typeof field === "undefined" || field === null)
      throw new Error(`필수 필드 누락: index ${idx}`);
  });
}

