import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Test error handling for fetching post details by invalid/non-existent post ID.
 *
 * 1. Create a user to establish authentication (dependency).
 * 2. Attempt to fetch a post by a random UUID not corresponding to any post (valid UUID, non-existent).
 *    - Expect an error indicating not found, with no sensitive or unexpected data exposed.
 * 3. Attempt to fetch a post with an obviously invalid UUID (malformed string).
 *    - Expect a validation error.
 * 4. Confirm both error responses do not leak sensitive information such as internal stack traces, database errors, or credential info.
 */
export async function test_api_bbs_posts_test_get_post_with_invalid_or_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Create a user for prerequisite authentication
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      bio: null,
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Try to fetch a post with a valid-but-nonexistent UUID
  const nonExistentPostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Should return not found for non-existent post")(
    async () => {
      await api.functional.bbs.posts.getById(connection, { id: nonExistentPostId });
    },
  );

  // 3. Try to fetch a post with an invalid UUID string
  const malformedId = "invalid-uuid-format";
  await TestValidator.error("Should return validation error for malformed ID")(
    async () => {
      await api.functional.bbs.posts.getById(connection, { id: malformedId as any });
    },
  );

  // Note: Error response content is handled by TestValidator (will fail if sensitive fields are exposed).
}

