import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Test creation of a new BBS post with valid user and category.
 *
 * This test validates successful workflows for creating a BBS post:
 *   1. Register a new discussion user who will author the post.
 *   2. Create a new discussion category that will be assigned to the post.
 *   3. Submit a new post that specifies the new category and author.
 *   4. Validate the returned post includes valid ID, author, category, and metadata.
 *   5. (Placeholder for post list/detail validation, as no read APIs provided)
 */
export async function test_api_bbs_test_create_post_with_valid_data(connection: api.IConnection) {
  // 1. Create a new user (who will author the post)
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphabets(8);
  const email = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password: "ValidPassw0rd!",
      bio: "Test user for post creation scenario", // Optional
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);
  TestValidator.equals("user.username")(username)(user.username);
  TestValidator.equals("user.email")(email)(user.email);
  TestValidator.equals("user_role_id")(userRoleId)(user.user_role_id);

  // 2. Create a new category
  const categoryName = RandomGenerator.alphabets(8);
  const categoryDesc = RandomGenerator.paragraph()();
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: categoryName,
      description: categoryDesc,
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);
  TestValidator.equals("category.name")(categoryName)(category.name);
  TestValidator.equals("category.description")(categoryDesc)(category.description);

  // 3. Create a new post with user and category
  const postTitle = RandomGenerator.paragraph()();
  const postContent = RandomGenerator.content()()();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      content: postContent,
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("post category")(category.id)(post.category_id);
  TestValidator.equals("post title")(postTitle)(post.title);
  TestValidator.equals("post content")(postContent)(post.content);

  // 4. Validate author and metadata
  TestValidator.equals("post.user_id")(user.id)(post.user_id);
  TestValidator.predicate("created_at - ISO8601")(!!post.created_at && /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.\d{3}Z$/.test(post.created_at));
  TestValidator.equals("not deleted")(null)(post.deleted_at ?? null);

  // 5. (Placeholder for list/detail endpoint, not available in provided API)
}

