import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Test updating a BBS post by its original author with valid data.
 *
 * This test covers the workflow for a registered user (author) updating their own post. It verifies correct category change, title/content update, and ensures all constraints are enforced (e.g., non-empty fields, valid category assignment). The test also checks that audit fields like 'updated_at' are refreshed appropriately and the returned post reflects all changes.
 *
 * 1. Register a user who will be the author of the post.
 * 2. Create two categories (initial and target – for reassignment).
 * 3. Author creates a post in the initial category.
 * 4. Author edits the post: changes title, content, and switches to the target category.
 * 5. Validate returned post data: all updates applied, both timestamps checked, category updated, fields non-empty.
 */
export async function test_api_bbs_posts_test_update_post_with_valid_data_by_author(connection: api.IConnection) {
  // 1. Register a user for authorship
  const userRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const username: string = RandomGenerator.alphabets(10);
  const email: string = `${RandomGenerator.alphabets(6)}@test.com`;
  const password: string = RandomGenerator.alphaNumeric(12);
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      role_id: userRoleId,
      bio: RandomGenerator.paragraph()(1),
    }
  });
  typia.assert(user);

  // 2. Create two categories: one for initial post, one for update target
  const categoryA = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(categoryA);
  const categoryB = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(categoryB);

  // 3. Author creates an initial post in CategoryA
  const originalTitle = RandomGenerator.paragraph()(1);
  const originalContent = RandomGenerator.content()(1)(2);
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryA.id,
      title: originalTitle,
      content: originalContent,
    },
  });
  typia.assert(post);

  // 4. The author updates the post with new title, content, and switch to CategoryB
  const newTitle = RandomGenerator.paragraph()(1);
  const newContent = RandomGenerator.content()(1)(2);
  const updateStart = new Date().toISOString();
  const updated = await api.functional.bbs.posts.putById(connection, {
    id: post.id,
    body: {
      category_id: categoryB.id,
      title: newTitle,
      content: newContent,
    },
  });
  typia.assert(updated);

  // 5. Validate all changes applied and constraints enforced
  TestValidator.equals("post.id")(post.id)(updated.id);
  TestValidator.equals("category updated")(categoryB.id)(updated.category_id);
  TestValidator.equals("title updated")(newTitle)(updated.title);
  TestValidator.equals("content updated")(newContent)(updated.content);
  TestValidator.predicate("updated_at after initial created_at")(
    updated.updated_at > post.created_at
  );
  TestValidator.predicate("updated_at after updateStart")(
    updated.updated_at >= updateStart
  );
  TestValidator.equals("author unchanged")(user.id)(updated.user_id);
  TestValidator.predicate("no deletion timestamp")(updated.deleted_at == null);
  TestValidator.predicate("non-empty title")(!!updated.title);
  TestValidator.predicate("non-empty content")(!!updated.content);
}

