      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

/**
 * Update a post's details (BBS: posts table).
 *
 * This API allows the original author (or, in special cases, a
 * moderator/administrator) to update an existing post identified by its UUID.
 * The client supplies updated values for title, content, or other modifiable
 * fields. The 'posts' table enforces that only the recorded author or
 * privileged account can submit updates to a given post record.
 *
 * The system maintains a history of 'updated_at' timestamps and can restrict
 * updates to within certain time windows, as described by business
 * requirements. Attempting to update with invalid data (missing or duplicate
 * title, empty content, invalid references) produces an error. Related
 * endpoints include post creation (POST), detailed retrieval (GET), and
 * deletion (DELETE).
 *
 * The API returns the updated post data upon success, immediately reflecting
 * any changes in subsequent queries.
 *
 * @param props.connection
 * @param props.id The unique post identifier to update.
 * @param props.body Updated values for the target post (title, content,
 *   category, etc.).
 * @path /bbs/posts/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function putById(
  connection: IConnection,
  props: putById.Props,
): Promise<putById.Response> {
  return !!connection.simulate
    ? putById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...putById.METADATA,
          path: putById.path(props),
          status: null,
        },
        props.body,
      );
}
export namespace putById {
  export type Props = {
    /** The unique post identifier to update. */
    id: string & tags.Format<"uuid">;

    /** Updated values for the target post (title, content, category, etc.). */
    body: bbsPosts.IUpdate;
  };
  export type Body = bbsPosts.IUpdate;
  export type Response = bbsPosts;

  export const METADATA = {
    method: "PUT",
    path: "/bbs/posts/:id",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Omit<Props, "body">) =>
    `/bbs/posts/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): bbsPosts =>
    typia.random<bbsPosts>(g);
  export const simulate = (
    connection: IConnection,
    props: putById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: putById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

