import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate that updating a post with invalid data is properly rejected by the API.
 *
 * This test checks the following invalid update scenarios:
 *   1. Assigning a non-existent category as the category_id
 *   2. Changing the title to a duplicate of another post (title must be unique)
 *   3. Providing an empty string for the title (title must be non-empty)
 *   4. Providing forbidden or banned content in the post's body (simulating moderation logic)
 *
 * Steps:
 * 1. Create a user (~author) for authentication context.
 * 2. Create at least one valid category.
 * 3. Create the original post for update attempts (by the created user).
 * 4. Attempt to update the post with each of the above invalid data cases, one by one.
 *    For each case, verify:
 *      - The API call fails (proper error is returned)
 *      - The post is not updated (i.e., data remains unchanged)
 */
export async function test_api_bbs_test_update_post_with_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a user (~author for the post)
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: RandomGenerator.email(),
      password: "strongPwd12345",
      bio: RandomGenerator.paragraph()(20),
      role_id: userRoleId,
    },
  });
  typia.assert(user);

  // 2. Create at least one valid category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(10),
    },
  });
  typia.assert(category);

  // 3. Create a post for update attempts
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.alphabets(12),
      content: RandomGenerator.paragraph()(30),
    },
  });
  typia.assert(post);

  // 3-1. Create another post for duplicate title test
  const anotherPost = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.alphabets(13),
      content: RandomGenerator.paragraph()(20),
    },
  });
  typia.assert(anotherPost);

  // Save original post details for later unchanged validation
  const original = { ...post };

  // 4. Attempt to update with invalid category_id (non-existent UUID)
  await TestValidator.error("update: non-existent category_id fails")(
    async () => {
      await api.functional.bbs.posts.putById(connection, {
        id: post.id,
        body: {
          category_id: typia.random<string & tags.Format<"uuid">>(),
          title: post.title,
          content: post.content,
        },
      });
    },
  );

  // 4. Attempt to update with duplicate title (from another post)
  await TestValidator.error("update: duplicate title fails")(
    async () => {
      await api.functional.bbs.posts.putById(connection, {
        id: post.id,
        body: {
          category_id: post.category_id,
          title: anotherPost.title,
          content: post.content,
        },
      });
    },
  );

  // 4. Attempt to update with empty title
  await TestValidator.error("update: empty title fails")(
    async () => {
      await api.functional.bbs.posts.putById(connection, {
        id: post.id,
        body: {
          category_id: post.category_id,
          title: "",
          content: post.content,
        },
      });
    },
  );

  // 4. Attempt to update with forbidden content
  await TestValidator.error("update: forbidden content fails")(
    async () => {
      await api.functional.bbs.posts.putById(connection, {
        id: post.id,
        body: {
          category_id: post.category_id,
          title: post.title,
          content: "This content contains banned words such as spam or abuse.",
        },
      });
    },
  );

  // 5. Validate post is unchanged after failed updates
  // (Re-fetch if a GET endpoint exists; else, compare with saved original)
  // For this example, we assume no GET so check main fields
  TestValidator.equals("post not changed")(original.title)(post.title);
  TestValidator.equals("post not changed")(original.content)(post.content);
}

