import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate that updating a post with invalid data is rejected and does not alter the post.
 *
 * This test covers the following invalid update scenarios:
 *   1. Assigning a non-existent category as the category_id
 *   2. Changing the title to a duplicate of another post (title must be unique)
 *   3. Providing an empty string for the title (title must be non-empty)
 *   4. Providing forbidden or banned content in the post's body (simulating moderation logic)
 *
 * Steps:
 * 1. Create a user to act as the author (users table)
 * 2. Create a valid category (categories table)
 * 3. Create an original post (posts table) to attempt updates on
 * 4. Create an additional post for duplicate title test
 * 5. For each invalid update scenario, attempt to update the post and verify:
 *    - The API call fails (error is thrown)
 *    - The post data is not changed (as far as can be verified)
 *
 * Note: Ideally, we'd query the post after each failed update to confirm its values are unchanged, but since no GET endpoint is given, we assert by comparing to the in-memory copy.
 */
export async function test_api_bbs_test_update_post_with_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a user (~author for the post)
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: RandomGenerator.email(),
      password: "StrongPwd!234",
      bio: RandomGenerator.paragraph()(20),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(user);

  // 2. Create a valid category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(10),
    },
  });
  typia.assert(category);

  // 3. Create the original post for update attempts
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.alphabets(12),
      content: RandomGenerator.paragraph()(30),
    },
  });
  typia.assert(post);

  // 4. Create a separate post for duplicate title test
  const anotherPost = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.alphabets(13),
      content: RandomGenerator.paragraph()(10),
    },
  });
  typia.assert(anotherPost);

  // Save original post state for comparison
  const original = { ...post };

  // 5-1. Non-existent category_id
  await TestValidator.error("update: invalid category_id should fail")(async () => {
    await api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        title: post.title,
        content: post.content,
      },
    });
  });

  // 5-2. Duplicate title
  await TestValidator.error("update: duplicate title should fail")(async () => {
    await api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: post.category_id,
        title: anotherPost.title,
        content: post.content,
      },
    });
  });

  // 5-3. Empty title
  await TestValidator.error("update: empty title should fail")(async () => {
    await api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: post.category_id,
        title: "",
        content: post.content,
      },
    });
  });

  // 5-4. Forbidden content
  await TestValidator.error("update: forbidden content should fail")(async () => {
    await api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: post.category_id,
        title: post.title,
        content: "This content contains banned words such as spam or abuse.",
      },
    });
  });

  // 6. Assert the original post is unchanged (as much as possible without GET)
  TestValidator.equals("title unchanged")(original.title)(post.title);
  TestValidator.equals("content unchanged")(original.content)(post.content);
  TestValidator.equals("category unchanged")(original.category_id)(post.category_id);
}

