import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate that a user who is neither the original author of a post nor a privileged user cannot update the post's content.
 *
 * This test ensures that only the post author (or a user with explicit privileged roles, e.g., moderator/admin, not provided here) is allowed to edit a post. Any other user should receive an authorization failure, and the post should remain unchanged.
 *
 * Steps:
 * 1. Create an author user with a random role and a normal user role (not moderator/admin).
 * 2. Create a distinct second user with the same type of role.
 * 3. Create a category for the post.
 * 4. Using the author user, create a post assigned to the created category.
 * 5. Switch to the second (non-author, non-privileged) user account.
 * 6. Attempt to update the post with new title/content/category.
 *    - Expected: The API should reject the attempt (typically 403 Forbidden or equivalent error).
