import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate successful deletion of a post by its author (soft delete/hard delete as per implementation).
 *
 * This test simulates the full business workflow of creating, then deleting, a post as its original author, and verifies that
the post is no longer visible. It ensures proper access controls (author can delete their own post), correct delete operation,
and effect on visibility in the system. The test focuses on end-user experience and business effect (not just technical API removal).
 *
 * Test workflow:
 * 1. Register a user who will create and delete the post.
 * 2. Register a new category (required for the post to be created).
 * 3. Create a post under the category as the registered user.
 * 4. Attempt to delete the post as the same user (simulate authentication).
 * 5. Confirm the deletion response indicates success (and if response includes deleted post, assert deleted_at is set correctly).
 * 6. Optionally, attempt to fetch the post by ID and expect an error or confirm deleted_at is set (if physically findable); if a post list endpoint exists, ensure the post is not listed.
 */
export async function test_api_bbs_test_delete_post_by_author(connection: api.IConnection) {
  // 1. Register a user
  // We need a unique role for registration, so generate a UUID for role_id.
  const userRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const username: string = RandomGenerator.alphaNumeric(8);
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(14);
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a category
  const categoryName: string = RandomGenerator.alphaNumeric(12);
  const categoryDescription: string = RandomGenerator.paragraph()();
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: categoryName,
      description: categoryDescription,
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create a post as the user
  const postTitle: string = RandomGenerator.paragraph()();
  const postContent: string = RandomGenerator.content()()();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      content: postContent,
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);
  // Optionally, check that the user_id matches our user
  TestValidator.equals("post.author matches user")(user.id)(post.user_id);

  // 4. Delete the post as the author
  const deleted = await api.functional.bbs.posts.eraseById(connection, {
    id: post.id,
  });
  typia.assert(deleted);

  // 5. Confirm the deleted post's deleted_at is set (for soft delete); if hard delete, this response may be not available or deleted post unreachable, so test accordingly.
  // If deleted_at property exists, check it is a date-time
  TestValidator.predicate("deleted_at should be set (soft delete)")(!!deleted.deleted_at);

  // 6. Optional: Try to fetch the post by id and expect not found or deleted_at set
  // This would require a GET endpoint, which is not defined in the provided API - so we skip live assertion of result. If there were a list endpoint, also filter to check absence.
}

