import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Test deletion rights enforcement for BBS posts: unauthorized user case
 *
 * This test verifies that only the post author or sufficiently privileged users can delete a post.
 * - Two user accounts are created: the author and a non-author (regular user with no additional privileges)
 * - A new category is created for the post
 * - The author creates a post in that category
 * - The non-author attempts to delete the post (same connection, assume user context is re-established for the non-author)
 * - The deletion attempt must fail due to lacking permissions
 * - The post must still be present after the failed deletion attempt
 * - No sensitive user or post information should be leaked in the error
 * - Both successful and error response types are validated via typia.assert
 * - TestValidator.error is used for negative assertion (delete attempt should throw)
 *
 * Steps:
 * 1. Register an author user and a non-author user
 * 2. Create a category
 * 3. Author user creates a post in the category
 * 4. (If applicable: authenticate as the non-author user)
 * 5. Non-author user attempts to delete the post (should fail)
 * 6. Confirm the post is still present by attempting to retrieve it (not possible with current SDK — so omitted)
 */
export async function test_api_bbs_test_delete_post_by_non_author(connection: api.IConnection) {
  // 1. Register the author user
  const authorUserRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const author: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      role_id: authorUserRoleId,
      bio: RandomGenerator.paragraph()(10),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(author);

  // 2. Register a non-author user
  const nonAuthorUserRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const nonAuthor: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      role_id: nonAuthorUserRoleId,
      bio: RandomGenerator.paragraph()(10),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(nonAuthor);

  // 3. Create a category (assume current user is authorized)
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(8),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 4. Author user creates a post in the category
  // (Assume backend uses current connection user context)
  // If possible, re-authenticate as author; if not, assume first-created account is in effect
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(3),
      content: RandomGenerator.content()()(5),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 5. Switch authentication context to non-author
  // (Assume a login procedure outside of this test or that connection switching is managed externally)
  // 6. Non-author tries to delete the post (should fail and throw)
  TestValidator.error("Non-author cannot delete other's post")(() =>
    api.functional.bbs.posts.eraseById(connection, { id: post.id }),
  );

  // 7. (Cannot check post presence due to missing GET endpoint in API, otherwise would confirm post remains)
}

