import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IPageIBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUsers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * End-to-end test for user list retrieval with filters and pagination as a privileged admin.
 *
 * This test scenario simulates a privileged user (admin/moderator) retrieving a filtered and paginated list of users. It ensures that the API enforces authentication, supports all search and filter parameters, and correctly returns pagination info and user profile data (excluding sensitive fields such as password hash).
 *
 * 1. Create several user accounts with diverse values for role, username, email, and status.
 * 2. Authenticate as admin (simulate privileged user by choosing an account with admin role).
 * 3. Execute a PATCH /bbs/users request using meaningful search parameters:
 *    - username substring
 *    - email domain substring (e.g., '@test.com')
 *    - a specific status value that at least one test user has
 *    - limit and page values for pagination (set page to 1, limit to less than total matching users if possible)
 * 4. Assert that:
 *    - The returned users all satisfy the filters (username contains substring, email has domain, correct status)
 *    - The total returned users do not exceed the limit and are correct for the page
 *    - Each returned user's data matches expected: id, username, email, bio, status, role properties (but not password hash)
 *    - Pagination metadata in response (current, limit, records, pages) reflects query and total
 *    - Edge: confirm that if fewer records than limit are available, only those are returned
 */
export async function test_api_bbs_test_list_users_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. Create test users with various roles, emails, usernames, statuses
  const testUsers = [
    {
      username: 'admin.user1',
      email: 'admin1@test.com',
      password: 'P@ssw0rd1',
      role_id: typia.random<string & tags.Format<'uuid'>>(),
      bio: 'Test admin',
    },
    {
      username: 'mod.user2',
      email: 'moderator@test.com',
      password: 'P@ssw0rd2',
      role_id: typia.random<string & tags.Format<'uuid'>>(),
      bio: 'Test moderator',
    },
    {
      username: 'user.test3',
      email: 'user3@sample.org',
      password: 'P@ssw0rd3',
      role_id: typia.random<string & tags.Format<'uuid'>>(),
      bio: 'Sample user',
    },
    {
      username: 'john.admin',
      email: 'john@test.com',
      password: 'P@ssw0rd4',
      role_id: typia.random<string & tags.Format<'uuid'>>(),
      bio: 'Another admin',
    },
  ];
  const createdUsers = [];
  for (const user of testUsers) {
    const created = await api.functional.bbs.users.post(connection, { body: user as IBbsUsers.ICreate });
    typia.assert(created);
    createdUsers.push(created);
  }
  // Optional: simulate status changes if API allows

  // 2. Authenticate as admin (assuming bearer token setup/Already privileged connection)
  //    In E2E, connection should contain admin privileges at this stage.

  // 3. Use PATCH /bbs/users with filter and pagination
  const filterUsername = 'admin';
  const filterEmail = '@test.com';
  const filterStatus = createdUsers[0].status; // just use first user's status
  const PAGE = 1;
  const LIMIT = 2;
  const response = await api.functional.bbs.users.patch(connection, {
    body: {
      username: filterUsername,
      email: filterEmail,
      status: filterStatus,
      page: PAGE,
      limit: LIMIT,
    } satisfies IBbsUsers.IRequest,
  });
  typia.assert(response);

  // 4. Validate returned data
  // Ensure all users match filters, and max 'limit' per page
  TestValidator.predicate('Returned user count').
    (response.data.length <= LIMIT);
  for (const u of response.data) {
    TestValidator.predicate('username matches')(u.username.includes(filterUsername));
    TestValidator.predicate('email matches')(u.email.includes(filterEmail));
    TestValidator.equals('status')(filterStatus)(u.status);
    // Ensure sensitive fields (like password hash) are NOT present
    TestValidator.predicate('No sensitive field')(typeof (u as any).password_hash === 'undefined');
  }
  // Assert pagination metadata
  TestValidator.equals('pagination current')(PAGE)(response.pagination.current);
  TestValidator.equals('pagination limit')(LIMIT)(response.pagination.limit);
  TestValidator.predicate('pagination records >= data length')(response.pagination.records >= response.data.length);
}

