/**
 * List users with search, filtering, and pagination (users table).
 *
 * This operation enables privileged users (moderators, administrators) to
 * retrieve a paginated list of all users registered on the discussion board.
 * The returned user data includes public profile information (username, email,
 * bio), their user role, account status, and registration metadata. Filtering
 * and searching capabilities provide powerful moderation and community
 * management tools, allowing admins to quickly investigate misuse, track new
 * registrations, or query dormant/suspended accounts. Pagination parameters
 * prevent excessive database load. The endpoint ensures security by requiring
 * bearer authentication and restricting access to users with sufficient
 * privileges (moderator or administrator). This operation references the users
 * Prisma schema model, specifically all columns described (id, user_role_id,
 * username, email, bio, status, created_at, updated_at). The response should
 * not include password hashes. Validation includes correct filter types, secure
 * pagination defaults, and correct authorization checks. This operation may be
 * combined with single-user lookup or management operations for a full user
 * administration workflow.
 *
 * @param props.connection
 * @param props.body Request parameters for user list/search, including filters,
 *   pagination, and sort details.
 * @path /bbs/users
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function patch(
  connection: IConnection,
  props: patch.Props,
): Promise<patch.Response> {
  return !!connection.simulate
    ? patch.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...patch.METADATA,
          path: patch.path(),
          status: null,
        },
        props.body,
      );
}
export namespace patch {
  export type Props = {
    /**
     * Request parameters for user list/search, including filters,
     * pagination, and sort details.
     */
    body: IBbsUsers.IRequest;
  };
  export type Body = IBbsUsers.IRequest;
  export type Response = IPageIBbsUsers;

  export const METADATA = {
    method: "PATCH",
    path: "/bbs/users",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/bbs/users";
  export const random = (g?: Partial<typia.IRandomGenerator>): IPageIBbsUsers =>
    typia.random<IPageIBbsUsers>(g);
  export const simulate = (
    connection: IConnection,
    props: patch.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: patch.path(),
      contentType: "application/json",
    });
    try {
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
