/**
 * Validate error handling for user listing with invalid filters.
 *
 * This test ensures that the user listing endpoint correctly handles invalid filter inputs and returns appropriate validation errors. In this scenario, we authenticate as an administrator and attempt to invoke the users list API with filters that are intentionally given invalid types or values (e.g., a malformed date string for registration date and an unrecognized status value). The expectation is that the API must reject these invalid inputs and return a validation error, confirming robust input validation and error handling.
 *
 * Steps:
 * 1. Authenticate as an administrator (assumed that the connection is already for an admin account as no dependency is provided).
 * 2. Attempt to list users passing an invalid date string (e.g., 'not-a-date') in 'registered_after' and an invalid status value (e.g., 'notastatus').
 * 3. Assert that the API throws a validation error (checked via TestValidator.error).
 */
export async function test_api_bbs_test_list_users_with_invalid_filter_type(connection: api.IConnection) {
  // Attempt to filter users with an invalid date and invalid status enum
  await TestValidator.error("rejects invalid date format and unrecognized status")(() =>
    api.functional.bbs.users.patch(connection, {
      body: {
        // valid pagination, but broken filters
        page: 1,
        limit: 10,
        status: "notastatus", // not a valid status per business logic
        registered_after: "not-a-date" as any, // force invalid date string
      } satisfies IBbsUsers.IRequest,
    })
  );
}

