/**
 * Validate that an administrator can successfully retrieve the full profile of a specific user via the admin context.
 *
 * 1. Register a new user with edge case data (long bio, special characters in fields).
 * 2. Use the resulting UUID to request the user profile through the admin path (as an admin context test).
 * 3. Validate that the returned profile contains all expected information:
 *   - ID, username, email, bio, timestamps, user_role_id, status, and full IBbsUserRoles subobject.
 *   - No credentials or sensitive info should be included.
 *   - Field values (including special characters/long bio) are returned correctly.
 */
export async function test_api_bbs_test_get_user_profile_success_by_admin(connection: api.IConnection) {
  // 1. Register a new user with edge-case fields
  const testRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const longBio =
    ArrayUtil.repeat(8)(() => RandomGenerator.paragraph()(RandomGenerator.number(32, 44))).join("\n")
    + " 😀#✨特殊記号€★";
  const created = await api.functional.bbs.users.post(connection, {
    body: {
      username: "admin.user_✨" + RandomGenerator.alphaNumeric(7),
      email: `special+edge.${RandomGenerator.alphaNumeric(6)}@mail.com`,
      password: "SecurePassw0rd$!",
      bio: longBio,
      role_id: testRoleId
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(created);

  // 2. As admin, retrieve the full profile for the created user
  const output = await api.functional.bbs.users.getById(connection, {
    id: created.id,
  });
  typia.assert(output);

  // 3. Validate expected fields and edge-case content
  TestValidator.equals("user id")(created.id)(output.id);
  TestValidator.equals("username matches")(created.username)(output.username);
  TestValidator.equals("email matches")(created.email)(output.email);
  TestValidator.equals("role ID matches")(created.user_role_id)(output.user_role_id);
  TestValidator.equals("status present")(typeof output.status, "string");
  TestValidator.predicate("created_at valid")(typeof output.created_at === "string" && output.created_at.length > 0);
  TestValidator.predicate("updated_at valid")(typeof output.updated_at === "string" && output.updated_at.length > 0);
  TestValidator.equals("bio matches")(created.bio)(output.bio);
  TestValidator.predicate("role subobject present")(typeof output.role === "object" && output.role !== null);
  // Check that special characters and long bio are preserved
  TestValidator.predicate("bio contains special chars")(
    typeof output.bio === "string" && output.bio.includes("特殊記号€★")
  );
  // No password or credential fields should be present
  if ((output as any).password || (output as any).password_hash) {
    throw new Error("No credentials should be exposed in profile!");
  }
}

