import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Test unauthorized access to another user's profile as a non-privileged user.
 *
 * This test ensures that a regular (non-admin, non-moderator) user cannot retrieve the profile of another user.
 * The business rule is that only privileged roles (self, moderator, admin) are permitted to view user profiles that do not belong to themselves, and all others must be restricted for privacy and audit requirements.
 *
 * Test Steps:
 * 1. Create User A (will be the target user whose profile will be accessed)
 * 2. Create User B (non-privileged user, who will attempt to access User A's profile)
 * 3. Using User B's (non-privileged user's) credentials, attempt to get User A's profile by ID.
 * 4. Confirm that access is forbidden (an error is thrown), i.e., user B is not allowed to view user A's profile.
 */
export async function test_api_bbs_test_get_user_profile_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Create User A (target user)
  const userARoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: `${RandomGenerator.alphaNumeric(8)}@test.com`,
      password: 'StrongPassword123!',
      role_id: userARoleId,
      bio: 'User A',
    },
  });
  typia.assert(userA);

  // 2. Create User B (non-privileged user)
  const userBRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: `${RandomGenerator.alphaNumeric(8)}@test.com`,
      password: 'StrongPassword123!',
      role_id: userBRoleId,
      bio: 'User B',
    },
  });
  typia.assert(userB);

  // (In a real system, would now authenticate as User B. For this test, assume simulated context, or the B user's token is loaded.)

  // 3. Attempt to retrieve User A's profile as User B
  await TestValidator.error("Non-privileged user cannot access another user's profile")(
    async () => {
      await api.functional.bbs.users.getById(connection, { id: userA.id });
    },
  );
}

