import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IPageIBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUserRoles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates successful creation of a new user account by an administrator.
 *
 * Ensures that the full workflow for admin-driven onboarding works by:
 * 1. Listing user roles to obtain a valid assignable role (dependency)
 * 2. Submitting all required user registration fields and an optional bio using unique, valid data
 * 3. Verifying the API returns a full user profile (excluding password), with correct role association, and supplied properties correctly set
 */
export async function test_api_bbs_test_create_user_with_valid_data(
  connection: api.IConnection,
) {
  // 1. List available user roles to obtain a usable role UUID
  const roleResponse = await api.functional.bbs.userRoles.patch(connection, {
    body: {
      page: 1,
      limit: 20,
      name: null,
      description: null,
    } satisfies IBbsUserRoles.IRequest,
  });
  typia.assert(roleResponse);
  const availableRoles = roleResponse.data;
  if (!availableRoles.length)
    throw new Error("No user roles available for user creation.");

  // Pick a valid role to assign
  const assignRole = RandomGenerator.pick(availableRoles);

  // 2. Prepare unique, well-formed account data
  const username = RandomGenerator.alphaNumeric(12);
  const email = `${username}@e2e-test.example.com`;
  const password = RandomGenerator.alphaNumeric(16);
  const bio = "Test bio for E2E - created at " + new Date().toISOString();

  // 3. Create user account
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      bio,
      role_id: assignRole.id,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 4. Validate response properties
  TestValidator.equals("username matches")(username)(user.username);
  TestValidator.equals("email matches")(email)(user.email);
  TestValidator.equals("bio matches")(bio)(user.bio);
  TestValidator.equals("role_id matches")(assignRole.id)(user.user_role_id);
  TestValidator.equals("role object matches")(assignRole.id)(user.role.id);
  TestValidator.equals("role name matches")(assignRole.name)(user.role.name);
  TestValidator.equals("role description matches")(assignRole.description)(user.role.description);

  // Ensure sensitive data (password) is never in the response
  if ((user as any).password !== undefined)
    throw new Error("Password must not be included in user profile response.");
}

