import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IPageIBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUserRoles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test user registration with duplicate username or email (uniqueness constraint).
 *
 * This test simulates the business situation where a new user attempts to register using a username or email that is already used by another account.
 * Uniqueness of email and username is enforced in the system. The test must ensure:
 * 1. At least one valid user role exists (required for user creation).
 * 2. Register an initial user with a unique username and email, assign a valid role.
 * 3. Attempt to register a second user with the same username (conflict), different email.
 * 4. Validate that an error is thrown due to unique username constraint.
 * 5. Attempt to register a third user with the same email (conflict), different username.
 * 6. Validate that an error is thrown due to unique email constraint.
 *
 * This ensures the backend enforces unique constraints and prevents duplicate accounts, protecting account integrity and preventing accidental duplication during onboarding or admin creation workflows.
 */
export async function test_api_bbs_test_create_user_with_duplicate_email_or_username(connection: api.IConnection) {
  // 1. Ensure at least one user role exists
  const rolesResponse = await api.functional.bbs.userRoles.patch(connection, {
    body: {}, // no filters, fetch all (use default pagination limit)
  });
  typia.assert(rolesResponse);
  const role = rolesResponse.data[0];
  if (!role)
    throw new Error("No user roles exist. Cannot create users without a role.");

  // 2. Register the initial user (unique username/email)
  const username = RandomGenerator.alphaNumeric(10);
  const email = `${RandomGenerator.alphaNumeric(10)}@example.com`;
  const password = RandomGenerator.alphaNumeric(12);
  const bio = RandomGenerator.paragraph()(1);
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      bio,
      role_id: role.id,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);
  TestValidator.equals("username matches")(username)(user.username);
  TestValidator.equals("email matches")(email)(user.email);

  // 3. Attempt to register with a duplicate username (should fail)
  await TestValidator.error("Duplicate username should fail")(async () => {
    await api.functional.bbs.users.post(connection, {
      body: {
        username, // duplicate username
        email: `${RandomGenerator.alphaNumeric(10)}@example.com`,
        password: RandomGenerator.alphaNumeric(12),
        bio: RandomGenerator.paragraph()(1),
        role_id: role.id,
      } satisfies IBbsUsers.ICreate,
    });
  });

  // 4. Attempt to register with a duplicate email (should fail)
  await TestValidator.error("Duplicate email should fail")(async () => {
    await api.functional.bbs.users.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email, // duplicate email
        password: RandomGenerator.alphaNumeric(12),
        bio: RandomGenerator.paragraph()(1),
        role_id: role.id,
      } satisfies IBbsUsers.ICreate,
    });
  });
}

