import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IPageIBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUserRoles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test user registration with invalid user role or badly formatted fields.
 *
 * This test verifies the backend validation logic for the user creation API by attempting to register users with various invalid inputs. It ensures that proper validation errors are triggered for each failing field, covering invalid role reference, email format, password constraints, and username constraints.
 *
 * Steps:
 * 1. Fetch available user roles so we can determine a valid role UUID and fabricate an invalid one.
 * 2. Craft registration data with:
 *    a) An invalid (non-existent) role ID
 *    b) An invalid email format
 *    c) An invalid password (too short or against policy)
 *    d) An invalid username (missing or against requirements)
 * 3. For each invalid case, attempt registration and assert validation error is thrown.
 * 4. For each case, confirm that the error is about the expected field (no need to check error type or message as per style guide).
 */
export async function test_api_bbs_test_create_user_with_invalid_role_or_format(connection: api.IConnection) {
  // 1. Fetch list of valid user roles to get a real role ID
  const rolesResp = await api.functional.bbs.userRoles.patch(connection, { body: {} });
  typia.assert(rolesResp);
  const validRoleId = rolesResp.data[0]?.id;
  const invalidRoleId = typia.random<string & tags.Format<"uuid">>();
  // Ensure invalidRoleId does not match any real ID
  if (rolesResp.data.find((r) => r.id === invalidRoleId)) {
    throw new Error("Random invalidRoleId matched a real role ID, rerun test.");
  }

  // 2a. Invalid role_id
  await TestValidator.error("invalid role_id should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: "validuser",
        email: "validuser@example.com",
        password: "ValidPassword123",
        role_id: invalidRoleId,
      } satisfies IBbsUsers.ICreate,
    }),
  );

  // 2b. Invalid email format
  await TestValidator.error("invalid email should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: "validuser",
        email: "not-an-email",
        password: "ValidPassword123",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    }),
  );

  // 2c. Invalid password (too short, assuming policy rejects <8 chars)
  await TestValidator.error("invalid password should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: "validuser",
        email: "validuser@example.com",
        password: "short",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    }),
  );

  // 2d. Invalid username (empty string)
  await TestValidator.error("invalid username should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: "",
        email: "validuser@example.com",
        password: "ValidPassword123",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    }),
  );
}

