  const rolesResp = await api.functional.bbs.userRoles.patch(connection, { body: {} });
  typia.assert(rolesResp);
  const validRoleId = rolesResp.data[0]?.id;
  if (!validRoleId) throw new Error("No user roles defined in the system.");
  let invalidRoleId = typia.random<string & tags.Format<"uuid">>();
  // Ensure invalidRoleId really does not match an actual role id
  while (rolesResp.data.some((r) => r.id === invalidRoleId)) {
    invalidRoleId = typia.random<string & tags.Format<"uuid">>();
  }

