  await TestValidator.error("invalid email should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: "validuser",
        email: "not-an-email",
        password: "ValidPassword123",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    }),
  );

  // 2c. Invalid password (too short, e.g., 5 chars)
  await TestValidator.error("invalid password should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: "validuser",
        email: "validuser@example.com",
        password: "short",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    }),
  );

  // 2d. Invalid username (empty string)
  await TestValidator.error("invalid username should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: "",
        email: "validuser@example.com",
        password: "ValidPassword123",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    }),
  );
}

