import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Test successful self-update of a user profile record.
 *
 * Simulates the flow where a new user is created (registered), then that same user attempts to update their own profile—including username, email, bio, and changing the assigned role (user_roles.id)—with all changes using valid, unique data. The sequence must verify:
 *   - That the self-update is accepted when valid (i.e., username/email/role remain unique and conformance rules are respected)
 *   - The updated response from the API exactly reflects submitted changes,
 *   - Uniqueness/integrity of username/email are preserved (no duplicates created)
 *
 * Workflow:
 * 1. Register a new user with unique credentials and a valid user_roles.id
 * 2. Attempt a PUT update to that user’s profile (with a new unique username, email, new bio, and new role_id)
 * 3. Confirm the updated response object correctly reflects updated values, and that the ID and created_at are unchanged.
 */
export async function test_api_bbs_test_update_user_profile_as_self_with_valid_data(connection: api.IConnection) {
  // 1. Register a new user who will be updated
  const originalUser: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      bio: RandomGenerator.paragraph()(1),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(originalUser);

  // 2. Update the user profile with new values
  const updatedUsername = RandomGenerator.alphaNumeric(12);
  const updatedEmail = typia.random<string & tags.Format<"email">>();
  const updatedBio = RandomGenerator.paragraph()(1);
  const updatedRoleId = typia.random<string & tags.Format<"uuid">>();

  const updated: IBbsUsers = await api.functional.bbs.users.putById(connection, {
    id: originalUser.id,
    body: {
      username: updatedUsername,
      email: updatedEmail,
      bio: updatedBio,
      role_id: updatedRoleId,
    } satisfies IBbsUsers.IUpdate,
  });
  typia.assert(updated);

