import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Test successful self-update of a user profile record.
 *
 * Simulates a realistic flow in which a user is registered with unique information, and then updates their own profile—including username, email, bio, and assigned role—with all values being valid and unique. The test verifies:
 *   - The update proceeds successfully when all validation rules are met (username, email, role are unique/valid)
 *   - The updated response exactly matches submitted changes
 *   - User ID and created_at remain stable, while updated_at is changed
 *   - Data integrity (no duplication) remains preserved
 *
 * Step-by-step process:
 * 1. Register a new user with unique credentials and a valid role_id
 * 2. Submit a self-profile update (PUT) for username, email, bio, and role_id
 * 3. Assert that the API response matches all updates, with unchanged id/created_at, incremented updated_at, and correct updated role
 */
export async function test_api_bbs_test_update_user_profile_as_self_with_valid_data(connection: api.IConnection) {
  // 1. Register a new user
  const originalUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      bio: RandomGenerator.paragraph()(1),
      role_id: typia.random<string & tags.Format<"uuid">>(),
