import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate the system correctly rejects updates to a user profile that would create a duplicate username or email.
 *
 * This test ensures the database uniqueness constraints on username and email are strictly enforced when updating user profiles. If an attempt is made to set the email or username of one user to a value already taken by a different user, the API should reject the update with a business logic error, and no changes should occur.
 *
 * Steps:
 * 1. Register two users (userA and userB) with distinct username/email/role/password.
 * 2. Attempt to update userB's profile, setting its username to userA's username. Confirm the API responds with an error and no modification proceeds.
 * 3. Attempt to update userB's profile, setting its email to userA's email. Again, confirm the API rejects the update.
 * 4. Optionally fetch userB after each error to verify its profile fields remain unchanged.
 *
 * This protects against accidental/intentional account impersonation and ensures the uniqueness guarantees for login/identity are never violated by API operations.
 */
export async function test_api_bbs_test_update_user_profile_with_duplicate_email_or_username(
  connection: api.IConnection,
) {
  // 1. Register userA
  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword_123!",
      bio: "Bio for userA",
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  // 2. Register userB
  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword_456!",
      bio: "Bio for userB",
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // Save userB's original details for later
  const originalB = { ...userB };

  // 3. Attempt to update userB's username to userA's username
  await TestValidator.error("duplicate username should be rejected")(() =>
    api.functional.bbs.users.putById(connection, {
      id: userB.id,
      body: {
        username: userA.username,
      } satisfies IBbsUsers.IUpdate,
    }),
  );

  // (Optional) Verify userB is unchanged by attempting an update with unique value and confirming it succeeds

  // 4. Attempt to update userB's email to userA's email
  await TestValidator.error("duplicate email should be rejected")(() =>
    api.functional.bbs.users.putById(connection, {
      id: userB.id,
      body: {
        email: userA.email,
      } satisfies IBbsUsers.IUpdate,
    }),
  );

  // Optionally: fetch/verify userB remains as originally registered
}

