  // 1. Register a normal user to be the deletion target
  const userRoleId: string = typia.random<string & tags.Format<"uuid">>(); // Substitute with actual member role id in integration
  const username = RandomGenerator.alphabets(8);
  const userEmail = `${RandomGenerator.alphabets(6)}@test.com`;
  const userPassword = RandomGenerator.alphabets(12);
  const normalUser = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email: userEmail,
      password: userPassword,
      bio: "Test account for soft delete",
      role_id: userRoleId,
    },
  });
  typia.assert(normalUser);

  // 2. Register an admin user (must have a true admin role_id)
  const adminRoleId: string = typia.random<string & tags.Format<"uuid">>(); // Substitute with actual admin role id if known in integration
  const adminUsername = RandomGenerator.alphabets(8);
  const adminEmail = `${RandomGenerator.alphabets(6)}@admin.com`;
  const adminPassword = RandomGenerator.alphabets(14);
  const adminUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      password: adminPassword,
      bio: "Soft delete admin",
      role_id: adminRoleId,
    },
  });
  typia.assert(adminUser);

  // 3. Authenticate as admin (Assuming connection reflects login context after registration, or skip if token mgmt not present)
  //    If authentication endpoints are present, they should be used here before deletion.
  //    In this sample, assume post sets up token for created user.

  // 4. Perform the soft-delete of the target user as an admin
  const deletedUser = await api.functional.bbs.users.eraseById(connection, {
    id: normalUser.id,
  });
  typia.assert(deletedUser);
  TestValidator.equals("user soft-deleted")("deleted")(deletedUser.status);

  // 5. Attempt to login as deleted user (SKIPPED: login endpoint not available)
  // If login endpoint was provided, would attempt login to verify access is blocked

  // 6. Verify audit fields remain
  TestValidator.equals("still same user id")(normalUser.id)(deletedUser.id);
  TestValidator.equals("role unchanged")(normalUser.user_role_id)(deletedUser.user_role_id);
  TestValidator.equals("username unchanged")(normalUser.username)(deletedUser.username);
  TestValidator.equals("email unchanged")(normalUser.email)(deletedUser.email);

  // 7. (If audit/content retrieval APIs were available, validate here that content is retained. Skipped.)
