/**
 * Validate that a non-privileged user (not an admin or the target user) cannot soft-delete (deactivate) another user's account.
 *
 * Business Context:
 * The API restricts account deactivation/removal privileges to administrators, moderators, or the account owner (self-removal). This test ensures that a regular user cannot deactivate another user's account and that an appropriate error is returned (e.g., permission denied or forbidden).
 *
 * Steps:
 * 1. Register two regular users: one as the target to be deleted, another as the acting (unauthorized) user.
 * 2. Attempt to soft-delete the target user while authenticated as the unauthorized (non-admin) user.
 * 3. Confirm that the operation fails with an error indicating insufficient permissions.
 * 4. If possible, confirm the target user remains in active status after the attempted deletion and was not modified as a result of the failure.
 */
export async function test_api_bbs_test_attempt_soft_delete_by_non_admin_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register a target user (to be deleted)
  const targetUserRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const targetUser: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      role_id: targetUserRoleId,
      bio: "Target user for deletion test",
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(targetUser);

  // 2. Register an acting (non-privileged) user
  const actorUserRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const actorUser: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      role_id: actorUserRoleId,
      bio: "User attempting unauthorized deletion",
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(actorUser);

  // (Assumed) Authenticate as the non-privileged user if API required; skipped if out of scope

  // 3. Attempt to soft-delete the target user (acting as the unauthorized user)
  await TestValidator.error("Non-admin should not be able to deactivate another user")(
    async () => {
      await api.functional.bbs.users.eraseById(connection, {
        id: targetUser.id,
      });
    },
  );

  // 4. (Optional) Confirm the target user still exists and is active
  // (API does not expose a get/read endpoint in the current SDK, so this step is omitted.)
}

