import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";
import type { IPageIBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsCommentReply";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the list of direct replies to a parent comment in a threaded discussion (BBS).
 *
 * Ensures:
 *   - Replies can only be fetched for a valid parent comment
 *   - Only direct (not nested/deep) replies are returned
 *   - Pagination and limit parameters are respected
 *   - The reply content and authors match the created replies
 *   - Fetching replies for a comment with no replies returns empty data
 *
 * Workflow:
 * 1. Register a BBS user and log in for authentication context
 * 2. Create a category for the post
 * 3. Create a post in this category as the user
 * 4. Post a comment to this post (becoming parent for replies)
 * 5. Add several replies (direct children) to this parent comment
 * 6. Test patchByCommentid endpoint with various pagination settings
 *     - Assert all replies returned have parent_id matching the parent comment
 *     - Assert reply details match what was posted
 *     - Validate correct response for page and limit settings
 * 7. Test fetching replies for a comment with no replies, confirm empty list
 */
export async function test_api_bbs_test_list_replies_to_comment_with_valid_parent_comment_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register a user
  // (Assume we need to select a user_role_id, not provided in flow, so using random)
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. Create a post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Create a parent comment
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Parent comment content",
    },
  });
  typia.assert(parentComment);

  // 5. Add multiple direct replies to parent comment
  const REPLY_COUNT = 5;
  const replies: IBbsCommentReply[] = [];
  for (let i = 0; i < REPLY_COUNT; ++i) {
    const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
      commentId: parentComment.id,
      body: {
        content: `Reply content #${i} to parent`,
      },
    });
    typia.assert(reply);
    replies.push(reply);
  }

  // 6. Test listing replies with various pagination options
  //   a) No pagination (default)
  const listing = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: {},
  });
  typia.assert(listing);
  TestValidator.equals("record count == REPLY_COUNT")(REPLY_COUNT)(listing.pagination.records);
  TestValidator.equals("all listed are direct replies")(true)(listing.data.every(r => r.parent_id === parentComment.id));
  for (const reply of replies) {
    const found = listing.data.find(r => r.id === reply.id);
    TestValidator.predicate(`Reply ${reply.id} listed`)(!!found);
    if (found) {
      TestValidator.equals(`Reply content matches for ${reply.id}`)(reply.content)(found.content);
      TestValidator.equals(`Reply user matches for ${reply.id}`)(reply.user_id)(found.user_id);
    }
  }

  //   b) Pagination with limit=2, page=1
  const listingLimit2 = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: { limit: 2, page: 1 },
  });
  typia.assert(listingLimit2);
  TestValidator.equals("pagination.limit == 2")(2)(listingLimit2.pagination.limit);
  TestValidator.equals("pagination.current == 1")(1)(listingLimit2.pagination.current);
  TestValidator.equals("pagination.pages")(
    Math.ceil(REPLY_COUNT / 2)
  )(listingLimit2.pagination.pages);
  TestValidator.predicate("data length matches limit or total for last page")(
    listingLimit2.data.length === 2 || listingLimit2.data.length === REPLY_COUNT % 2
  );
  TestValidator.equals("all listed are direct replies (limit2 page1)")(true)(
    listingLimit2.data.every(r => r.parent_id === parentComment.id)
  );

  //   c) Pagination, page beyond last
  const listingBeyond = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: { limit: 2, page: 99 },
  });
  typia.assert(listingBeyond);
  TestValidator.equals("empty page on out-of-range page index")(0)(listingBeyond.data.length);

  // 7. Test fetching replies for a comment with no replies
  const loneComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Lone comment with no replies",
    },
  });
  typia.assert(loneComment);
  const loneListing = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: loneComment.id,
    body: {},
  });
  typia.assert(loneListing);
  TestValidator.equals("no replies to lone comment == 0")(0)(loneListing.data.length);
}

