import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";
import type { IPageIBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsCommentReply";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 삭제(soft-delete)된 부모 댓글(replies를 가질 수 있는 댓글)에 대해 답글 리스트 요청 시 적절한 접근 제어 및 에러 처리 검증
 *
 * 1. 사용자 계정 생성 (api.functional.bbs.users.post)
 * 2. 카테고리 생성 (api.functional.bbs.categories.post)
 * 3. 게시글 생성 (api.functional.bbs.posts.post)
 * 4. 게시글에 상위 댓글 등록 (api.functional.bbs.posts.comments.postByPostid)
 * 5. 상위 댓글을 soft-delete 처리 (api.functional.bbs.posts.comments.eraseByPostidAndId)
 * 6. 삭제된 부모댓글의 답글 리스트 요청 (api.functional.bbs.comments.comments.patchByCommentid) 시 비어있는 결과 또는 적절한 에러 반환을 검증
 *
 * 주요 검증 포인트:
 * - 삭제된(soft-deleted) 부모댓글에 대해 답글을 조회할 수 없는지 확인 (API의 정책에 따라 empty list 혹은 error가 반환되어야 함)
 * - 권한 및 논리적 위반이 없음을 검증 (UNAUTHORIZED/NOT_FOUND 혹은 정상 조회지만 data가 empty)
 *
 * 세부 과정:
 * 1. 신규 사용자 회원가입 (username/email/password/random, 일반 권한)
 * 2. 카테고리 등록 (name/description random)
 * 3. 게시글 등록 (category 연결, title/content random)
 * 4. 댓글 등록 (게시글 연관, parent_id=null의 상위댓글)
 * 5. 댓글 soft-delete (삭제시도)
 * 6. patchByCommentid(삭제된 댓글id)로 답글 조회시 data가 empty 또는 적절한 에러인지 검증
 */
export async function test_api_bbs_test_list_replies_to_deleted_parent_comment(connection: api.IConnection) {
  // 1. 사용자 회원가입
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: RandomGenerator.alphabets(8) + "@test.com",
      password: "Password1234!",
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: null
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(user);

  // 2. 카테고리 등록
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(1)
    }
  });
  typia.assert(category);

  // 3. 게시글 등록
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()(1)() 
    }
  });
  typia.assert(post);

  // 4. 댓글 등록 (상위댓글, parent_id 없음)
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: { content: RandomGenerator.paragraph()(1) }
  });
  typia.assert(parentComment);

  // 5. 댓글 soft-delete (삭제)
  await api.functional.bbs.posts.comments.eraseByPostidAndId(connection, {
    postId: post.id,
    id: parentComment.id
  });

  // 6. 삭제된 부모댓글의 답글 요청
  await TestValidator.error("deleted parent comment's replies should not be accessible")(
    async () => {
      const replies = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
        commentId: parentComment.id,
        body: {} as IBbsCommentReply.IRequest
      });
      // 정책에 따라 빈 목록이 반환될 수도 있으므로, 정책상 허용될 경우 아래로 대체:
      // typia.assert(replies);
      // TestValidator.equals("no replies on deleted parent comment")([], replies.data);
    }
  );
}

