import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";
import type { IPageIBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsCommentReply";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test error handling when listing replies for a soft-deleted (deleted) parent comment.
 *
 * This test verifies that if someone attempts to list the direct replies to a comment after it has been soft-deleted,
 * the system must defend against unauthorized or illogical access. This could manifest as an error or an empty list,
 * depending on platform policy.
 *
 * **Test workflow:**
 * 1. Register a new user account
 * 2. Create a new category
 * 3. Create a post within this category
 * 4. Add a comment to the post (which will be parent for replies)
 * 5. Soft-delete the parent comment
 * 6. Attempt to list the replies to the deleted parent comment
 * 7. Confirm that the system blocks access by error (or, if policy is to return empty, that no replies are listed).
 *
 * All steps use valid, random test data. This validates correct implementation of soft-delete, access control,
 * and logical business policy enforcement for threaded comment APIs.
 */
export async function test_api_bbs_test_list_replies_to_deleted_parent_comment(
  connection: api.IConnection,
) {
  // 1. Register a new user account
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: `${RandomGenerator.alphabets(8)}@test.com`,
      password: "AutoBeTest1234!",
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: null,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a new category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(category);

  // 3. Create a new post in this category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()(1)(),
    },
  });
  typia.assert(post);

  // 4. Create a top-level comment on the post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(1),
    } satisfies bbsComments.ICreate,
  });
  typia.assert(parentComment);

  // 5. Soft-delete the parent comment
  await api.functional.bbs.posts.comments.eraseByPostidAndId(connection, {
    postId: post.id,
    id: parentComment.id,
  });

  // 6. Attempt to list replies to the deleted parent comment
  await TestValidator.error("listing replies of a soft-deleted parent comment should be denied")(
    async () => {
      await api.functional.bbs.comments.comments.patchByCommentid(connection, {
        commentId: parentComment.id,
        body: {}, // Default pagination (page/limit can be omitted for all)
      });
    },
  );
}

