import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IBbsCommentReply } from "../../../../structures/IBbsCommentReply";
import { IPageIBbsCommentReply } from "../../../../structures/IPageIBbsCommentReply";

/**
 * List all direct replies to a specific comment (comments table, threaded
 * replies).
 *
 * This operation retrieves a paginated and optionally filtered list of replies
 * to a specific parent comment. The 'comments' table supports self-referential
 * relationships for nested replies via the 'parent_id' field. Each retrieved
 * comment must have 'parent_id' matching the provided 'commentId'.
 *
 * Standard search, filtering, and pagination options are supported via the
 * request body. Only direct (not deeply nested) children are included. The
 * operation checks if the parent comment exists and is not deleted. If access
 * to the replies is restricted (e.g., if the parent comment is deleted or
 * private), the API must enforce rules accordingly.
 *
 * This operation is commonly used in threaded conversation UIs and supports
 * constructing the hierarchy of replies for discussion depth and transparency.
 *
 * @param props.connection
 * @param props.commentId Target parent comment's ID whose direct children are
 *   queried.
 * @param props.body Search and pagination options for replies to the comment.
 * @path /bbs/comments/:commentId/comments
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function patchByCommentid(
  connection: IConnection,
  props: patchByCommentid.Props,
): Promise<patchByCommentid.Response> {
  return !!connection.simulate
    ? patchByCommentid.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...patchByCommentid.METADATA,
          path: patchByCommentid.path(props),
          status: null,
        },
        props.body,
      );
}
export namespace patchByCommentid {
  export type Props = {
    /** Target parent comment's ID whose direct children are queried. */
    commentId: string & tags.Format<"uuid">;

    /** Search and pagination options for replies to the comment. */
    body: IBbsCommentReply.IRequest;
  };
  export type Body = IBbsCommentReply.IRequest;
  export type Response = IPageIBbsCommentReply;

  export const METADATA = {
    method: "PATCH",
    path: "/bbs/comments/:commentId/comments",
    request: {
      type: "application/json",
      encrypted: false,
    },
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Omit<Props, "body">) =>
    `/bbs/comments/${encodeURIComponent(props.commentId ?? "null")}/comments`;
  export const random = (
    g?: Partial<typia.IRandomGenerator>,
  ): IPageIBbsCommentReply => typia.random<IPageIBbsCommentReply>(g);
  export const simulate = (
    connection: IConnection,
    props: patchByCommentid.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: patchByCommentid.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("commentId")(() => typia.assert(props.commentId));
      assert.body(() => typia.assert(props.body));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

