import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate the successful retrieval of reply details for a valid nested reply under a parent comment.
 *
 * Business context: In a threaded BBS, users can reply to comments, forming conversation threads. Retrieving a reply detail requires proper linkage through both parent comment and reply IDs. This test ensures that a direct reply can be accurately retrieved only when it matches the given parent, and that returned data contains the correct detail structure, with no sensitive or hidden fields leaked to ordinary users.
 *
 * Step-by-step process:
 * 1. Register a user with a random username, email, password, role ID, and optional bio.
 * 2. Create a category for post assignment.
 * 3. Create a post in the new category as the test user.
 * 4. Add a first-level comment to the post (this becomes the parent comment for replies).
 * 5. Post a direct reply to the above comment, forming a nested thread (capture its ID and parent comment ID).
 * 6. Fetch the reply details by specifying both the parent comment ID and the nested reply ID using the GET endpoint.
 * 7. Validate that all returned fields match the created reply's data: reply ID, content, parent_id, post_id, user_id, created/updated timestamps, and soft-deletion flag if any.
 * 8. Assert that no unintended or hidden fields (such as password or internal audit metadata) are present in the response.
 */
export async function test_api_bbs_test_get_reply_details_with_valid_reply_and_permission(connection: api.IConnection) {
  // 1. Register a user
  const roleId = typia.random<string & tags.Format<"uuid">>(); // Randomly simulate a user role
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(6) + "@email.com",
      password: RandomGenerator.alphaNumeric(12),
      bio: RandomGenerator.paragraph()(),
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a category for post assignment
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. Create a post in the new category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 4. Add a first-level comment to the post
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(comment);

  // 5. Post a direct reply to the above comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(reply);
  // Validate reply fields match expectations
  TestValidator.equals("reply.parent_id == comment.id")(comment.id)(reply.parent_id);
  TestValidator.equals("reply.post_id == post.id")(post.id)(reply.post_id);
  TestValidator.equals("reply.content non-empty")(true)(reply.content.length > 0);

  // 6. Retrieve the reply details
  const fetched = await api.functional.bbs.comments.comments.getByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
  });
  typia.assert(fetched);

  // 7. Validate fetched reply matches the created reply in all fields
  TestValidator.equals("id matches")(reply.id)(fetched.id);
  TestValidator.equals("user_id matches")(reply.user_id)(fetched.user_id);
  TestValidator.equals("post_id matches")(reply.post_id)(fetched.post_id);
  TestValidator.equals("parent_id matches")(reply.parent_id)(fetched.parent_id);
  TestValidator.equals("content matches")(reply.content)(fetched.content);
  TestValidator.equals("created_at matches")(reply.created_at)(fetched.created_at);
  TestValidator.equals("updated_at matches")(reply.updated_at)(fetched.updated_at);
  TestValidator.equals("deleted_at matches")(
    (reply.deleted_at ?? null)
  )((fetched.deleted_at ?? null));

  // 8. Assert no sensitive or hidden fields leak to regular users
  // All expected fields: id, user_id, post_id, parent_id, content, created_at, updated_at, deleted_at
  // Check no additional property exists
  const allowedFields = [
    "id",
    "user_id",
    "post_id",
    "parent_id",
    "content",
    "created_at",
    "updated_at",
    "deleted_at",
  ];
  const extraKeys = Object.keys(fetched).filter((key) => !allowedFields.includes(key));
  TestValidator.equals("no extra fields leak")(0)(extraKeys.length);
}

