  TestValidator.equals("reply.post_id == post.id")(post.id)(reply.post_id);
  TestValidator.equals("reply.content non-empty")(true)(reply.content.length > 0);

  // 6. Retrieve the reply details
  const fetched = await api.functional.bbs.comments.comments.getByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
  });
  typia.assert(fetched);

