  TestValidator.equals("user_id matches")(reply.user_id)(fetched.user_id);
  TestValidator.equals("post_id matches")(reply.post_id)(fetched.post_id);
  TestValidator.equals("parent_id matches")(reply.parent_id)(fetched.parent_id);
  TestValidator.equals("content matches")(reply.content)(fetched.content);
  TestValidator.equals("created_at matches")(reply.created_at)(fetched.created_at);
  TestValidator.equals("updated_at matches")(reply.updated_at)(fetched.updated_at);
  TestValidator.equals("deleted_at matches")(
    (reply.deleted_at ?? null)
  )((fetched.deleted_at ?? null));

  // 8. Assert no sensitive or hidden fields leak to regular users
  // All expected fields: id, user_id, post_id, parent_id, content, created_at, updated_at, deleted_at
  // Check no additional property exists
  const allowedFields = [
    "id",
    "user_id",
    "post_id",
    "parent_id",
    "content",
    "created_at",
    "updated_at",
    "deleted_at",
  ];
  const extraKeys = Object.keys(fetched).filter((key) => !allowedFields.includes(key));
  TestValidator.equals("no extra fields leak")(0)(extraKeys.length);
