import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate error/hidden-resource logic when requesting a reply that has been soft-deleted.
 *
 * This test verifies the system's response when trying to fetch details of a nested comment (reply) after it has been soft-deleted. All dependent resources — user, category, post, comment, reply — are created during setup. The reply is then soft-deleted, and an attempt is made to fetch its details directly. The system should enforce that such deleted replies are not retrievable (or do not expose sensitive content if returned).
 *
 * Steps:
 * 1. Register a user account for all subsequent actions.
 * 2. Create a category for grouping posts.
 * 3. Create a post to host comments.
 * 4. Write a top-level comment on the post.
 * 5. Create a nested reply to that comment.
 * 6. Soft-delete the reply comment.
 * 7. Try to fetch the details of the deleted reply and verify that the system disallows access or returns an appropriate error/state.
 *
 * Key validations:
 * - The deleted reply should not be retrievable with its content available.
 * - The API should either throw an error or, if it does return an object, it must have the 'deleted_at' field set and redact content appropriately.
 * - If an error is thrown, this should be explicitly asserted as a success case (not a test failure).
 */
export async function test_api_bbs_test_get_reply_details_for_deleted_reply(connection: api.IConnection) {
  // 1. Register a user.
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(8) + '@test.local',
      password: RandomGenerator.alphaNumeric(12),
      role_id: typia.random<string & tags.Format<'uuid'>>(),
      bio: null,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a category.
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(category);

  // 3. Create a post in the category.
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.paragraph()(2),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Create a top-level comment.
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: { content: RandomGenerator.paragraph()(1) } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);

  // 5. Create a reply (nested comment) to the first comment.
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: { content: RandomGenerator.paragraph()(1) } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(reply);

  // 6. Soft-delete the reply.
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
  });

  // 7. Attempt to fetch the deleted reply - should produce an error or return deleted info.
  await TestValidator.error('Fetching a soft-deleted reply should not return accessible content')(
    async () => {
      const deleted = await api.functional.bbs.comments.comments.getByCommentidAndId(connection, {
        commentId: comment.id,
        id: reply.id,
      });
      typia.assert(deleted);
      // If system does not throw, further assert that deleted_at is set
      TestValidator.predicate('deleted_at should be set')(!!deleted.deleted_at);
