import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test creation of a nested (threaded) reply to an existing comment by an authenticated user.
 *
 * This test verifies the following workflow and validates both data integrity and API business rules:
 * 1. A user account is registered to authenticate further actions.
 * 2. A category is created as the container for posts.
 * 3. A post is created in the category by the user.
 * 4. The user creates a root-level comment on the post.
 * 5. The user submits a reply to the parent comment with valid content.
 * 6. Validates:
 *    - The reply is associated with the correct parent comment via parent_id.
 *    - The reply's author matches the user (user_id).
 *    - The reply references the same post (post_id).
 *    - The reply's content and timestamps are present and properly formatted.
 */
export async function test_api_bbs_test_create_reply_to_comment_with_valid_auth_and_data(
  connection: api.IConnection,
) {
  // 1. Register a user
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphaNumeric(8);
  const email = `${RandomGenerator.alphaNumeric(6)}@example.com`;
  const password = randomPassword();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      role_id: userRoleId,
      bio: RandomGenerator.paragraph()(1),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a category for posts
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(category);

  // 3. Create a post in the category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()(1)(),
    },
  });
  typia.assert(post);

  // 4. Add a parent comment to the post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.content()(1)(),
      parent_id: null, // Top-level comment
    },
  });
  typia.assert(parentComment);

  // 5. Submit a reply to the parent comment
  const replyContent = RandomGenerator.content()(1)();
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: replyContent,
    },
  });
  typia.assert(reply);

  // 6. Validate reply association and integrity
  TestValidator.equals("parent_id should match parent comment")(
    parentComment.id,
  )(reply.parent_id ?? undefined);
  TestValidator.equals("reply's post_id matches parent comment's post_id")(
    parentComment.post_id,
  )(reply.post_id);
  TestValidator.equals("author of reply matches the test user")(
    user.id,
  )(reply.user_id);
  TestValidator.equals("reply content matches what was submitted")(
    replyContent,
  )(reply.content);
  TestValidator.predicate("created_at is ISO8601 format and present")(
    typeof reply.created_at === "string" &&
      !isNaN(Date.parse(reply.created_at)),
  );
  TestValidator.predicate("updated_at is ISO8601 format and present")(
    typeof reply.updated_at === "string" &&
      !isNaN(Date.parse(reply.updated_at)),
  );
}

function randomPassword() {
  // Minimum 8 chars with alpha-numeric content
  return RandomGenerator.alphaNumeric(10);
}

