import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate that reply creation (nested comment) fails appropriately when given invalid input or when unauthenticated.
 *
 * Business context: Comments and their replies form discussion threads. The API must enforce: (a) validation (non-empty content), and (b) proper authentication.
 *
 * Step-by-step process:
 * 1. Register a regular user (for authentication context)
 * 2. Create a category to allow post insertion
 * 3. Create a post by the user
 * 4. Insert a first-level comment (parent comment)
 * 5. Test reply creation with missing content (should yield validation error)
 * 6. Test reply creation with empty string content (should yield validation error)
 * 7. Test reply creation with valid content but no authentication (should yield authentication error)
 * 8. Confirm that all validation and authentication rules are enforced.
 */
export async function test_api_bbs_test_create_reply_with_invalid_data_or_unauthorized(connection: api.IConnection) {
  // 1. Register user
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphabets(6) + "@example.com",
      password: "TestPwd1234!",
      bio: "Test bio",
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Insert post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Insert parent comment
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.content()()(),
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);

  // 5. REPLY CREATION ATTEMPT with missing content (validation error)
  // Can't omit content field in TypeScript, so skip if not possible

  // 6. REPLY CREATION ATTEMPT with empty string content (validation error)
  await TestValidator.error("empty content is invalid for reply")(() =>
    api.functional.bbs.comments.comments.postByCommentid(connection, {
      commentId: comment.id,
      body: { content: "" } satisfies IBbsCommentReply.ICreate,
    })
  );

  // 7. REPLY CREATION ATTEMPT with no authentication (authentication error)
  // Remove token from connection
  const unauthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("creating reply without authentication fails")(() =>
    api.functional.bbs.comments.comments.postByCommentid(unauthConn, {
      commentId: comment.id,
      body: { content: RandomGenerator.paragraph()() } satisfies IBbsCommentReply.ICreate,
    })
  );
}

