import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate that reply creation (nested comment) fails when given invalid input or when unauthenticated.
 *
 * Business context: Replies (nested comments) underpin threaded discussions. The API must enforce data and access integrity rules.
 *
 * Steps:
 * 1. Register a new user (provides authentication context)
 * 2. Create a category
 * 3. Create a post in the category
 * 4. Add a top-level comment (to reply to)
 * 5. Attempt reply creation with empty string content: must fail with validation error
 * 6. Attempt reply creation with valid content but with NO authentication: must fail with authentication error
 * 7. Confirm API enforces both validation and authentication rules
 */
export async function test_api_bbs_test_create_reply_with_invalid_data_or_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register a user
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphabets(6) + "@example.com",
      password: "TestPwd1234!",
      bio: "Test bio",
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create a post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Add a top-level comment to the post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.content()()(),
    } satisfies bbsComments.ICreate,
  });
  typia.assert(parentComment);

  // 5. Attempt to create a reply comment with empty content (validation error expected)
  await TestValidator.error("reply with empty content should fail validation")(() =>
    api.functional.bbs.comments.comments.postByCommentid(connection, {
      commentId: parentComment.id,
      body: { content: "" } satisfies IBbsCommentReply.ICreate,
    })
  );

  // 6. Attempt to create a reply as an unauthenticated user (authentication error expected)
  const unauthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthenticated reply creation should fail")(() =>
