import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate error handling when replying to a non-existent comment.
 *
 * This test ensures the API correctly prevents posting a reply beneath a comment ID that does not exist in the system. It follows realistic business logic:
 *
 * 1. Register a user to obtain a valid authentication token (required for all posting actions).
 * 2. Attempt to post a reply using a random (but validly formatted) UUID as the parent commentId, which is not associated with any existing comment in the database.
 * 3. Use a legitimate reply body with random but valid content.
 * 4. Ensure that the API returns an appropriate "not found" error or business error indicating that the target parent comment does not exist.
 *
 * Rationale: This protects the integrity of thread hierarchies by enforcing that only existing comments may receive replies. It is a critical authorization and validation check.
 *
 * Steps:
 * 1. Create a user
 * 2. Attempt posting a reply using a non-existent commentId
 * 3. Expect an error and validate that it occurred
 */
export async function test_api_bbs_test_create_reply_to_nonexistent_parent_comment(
  connection: api.IConnection,
) {
  // 1. Register a user
  const userRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphabets(12),
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Attempt to reply to a non-existent comment
  const nonExistentCommentId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Reply to non-existent comment should fail")(
    async () => {
      await api.functional.bbs.comments.comments.postByCommentid(connection, {
        commentId: nonExistentCommentId,
        body: {
          content: RandomGenerator.paragraph()(),
        } satisfies IBbsCommentReply.ICreate,
      });
    },
  );
}

