import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate permissions and behavior when updating a reply comment as its original author.
 *
 * This test simulates a realistic scenario in which the author of a reply attempts to update their message, and checks that only the rightful owner (or a privileged moderator) can perform the operation, with all audit information intact. It also ensures non-owners are denied permission.
 *
 * Steps:
 * 1. Register an initial (owner) user, and a second (non-owner) user for the privilege test.
 * 2. Create a BBS category using a random name and description.
 * 3. With the owner user, create a post in the new category.
 * 4. As owner, add a top-level comment to the post.
 * 5. As owner, add a reply to the top-level comment.
 * 6. Update the reply as its owner; validate response reflects the new content, the updated_at timestamp is newer, and user_id stays the same.
 * 7. Attempt to update the reply as the second (non-owner) user; confirm an error occurs, indicating forbidden access.
 */
export async function test_api_bbs_test_update_reply_with_valid_owner_and_data(connection: api.IConnection) {
  // 1. Register owner user
  const ownerRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const ownerReg = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "ownerPass123!",
      bio: "Owner user for reply update test.",
      role_id: ownerRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(ownerReg);

  // 2. Register another user (non-owner)
  const otherRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const nonOwnerReg = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "nonOwnerPass456#",
      bio: "Non-owner for forbidden update test.",
      role_id: otherRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(nonOwnerReg);

  // 3. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 4. Create post by owner user
  // (simulate login/session if needed; here assumed connection is owner for this step)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 5. Owner creates a top-level comment
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(),
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);

  // 6. Owner creates a reply (nested comment)
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: "First reply content.",
    } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(reply);

  // 7. Update the reply as the owner
  const updatedContent = "Updated reply body by owner.";
  const updatedReply = await api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
    body: {
      content: updatedContent,
    } satisfies IBbsCommentReply.IUpdate,
  });
  typia.assert(updatedReply);

  // Validate that content updated, updated_at is newer, and user_id and post_id unchanged
  TestValidator.equals("updated content")(updatedContent)(updatedReply.content);
  TestValidator.equals("same reply ID")(reply.id)(updatedReply.id);
  TestValidator.equals("same parent (comment) ID")(reply.parent_id)(updatedReply.parent_id);
  TestValidator.equals("same post ID")(reply.post_id)(updatedReply.post_id);
  TestValidator.equals("author unchanged")(reply.user_id)(updatedReply.user_id);
  TestValidator.predicate("updated_at is newer")(Date.parse(updatedReply.updated_at) > Date.parse(reply.updated_at));

  // Attempt update as non-owner user (should fail with forbidden or not permitted)
  // (simulate login/session as nonOwner here if needed; reuse connection or switch token as needed)
  await TestValidator.error("non-owner forbidden update")(
    async () => {
      await api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
        commentId: comment.id,
        id: reply.id,
        body: {
          content: "Evil update by non-owner user.",
        } satisfies IBbsCommentReply.IUpdate,
      });
    },
  );
}

