import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate failure when trying to update a reply with invalid content or after soft-deletion.
 *
 * This test ensures two key error scenarios for reply updates:
 *   1. The system rejects updates when content is empty (invalid update).
 *   2. The system rejects updates to a reply that has already been soft-deleted.
 *
 * Business context:
 * - Ensures platform moderation and data integrity by enforcing validation and edit/delete separation rules for comment replies.
 * - Users should not be able to update a reply’s text to an invalid (empty) state, nor alter a reply after it’s been deleted (soft-deleted for audit purposes).
 *
 * Test Steps:
 * 1. Register a user for authorship.
 * 2. Create a category for posts.
 * 3. Create a post in that category.
 * 4. Add a parent comment to the post.
 * 5. Add a reply to the parent comment.
 * 6. Attempt to update the reply with empty content (expect failure).
 * 7. Delete (soft-delete) the reply.
 * 8. Attempt to update the already-deleted reply (expect failure).
 */
export async function test_api_bbs_test_update_reply_with_invalid_content_or_deleted_reply(
  connection: api.IConnection,
) {
  // 1. Register user for authorship
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: RandomGenerator.paragraph()(20),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(15),
    },
  });
  typia.assert(category);

  // 3. Create a post in the category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.alphabets(16),
      content: RandomGenerator.paragraph()(50),
    },
  });
  typia.assert(post);

  // 4. Add a parent comment to the post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(10),
    },
  });
  typia.assert(parentComment);

  // 5. Add a reply to the parent comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: RandomGenerator.paragraph()(7),
    },
  });
  typia.assert(reply);

  // 6. Attempt to update the reply with invalid (empty) content
  await TestValidator.error("empty reply content update should fail")(async () => {
    await api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: parentComment.id,
      id: reply.id,
      body: {
        content: "",
      },
    });
  });

  // 7. Delete (soft-delete) the reply
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: parentComment.id,
    id: reply.id,
  });

  // 8. Attempt to update the already-deleted reply (should fail)
  await TestValidator.error("cannot update already deleted reply")(async () => {
    await api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: parentComment.id,
      id: reply.id,
      body: {
        content: RandomGenerator.paragraph()(8),
      },
    });
  });
}

