import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate permission enforcement when updating a reply comment by unauthorized users.
 *
 * This test ensures that only the creator of a reply comment may update it. 
 * Specifically, it tests two negative scenarios:
 *  1. A different user (not the author) attempts to update the reply (should be rejected)
 *  2. An unauthenticated (anonymous) client attempts to update the reply (should be rejected)
 *
 * The steps performed in this test:
 * 1. Register two user accounts (userA and userB)
 * 2. Create a category for post hierarchy
 * 3. Log in as userA and create a post in the category
 * 4. As userA, create a top-level comment on the post
 * 5. As userA, create a reply to the top-level comment
 * 6. Switch authentication to userB and attempt to update the reply (should fail with permission error)
 * 7. Remove authentication (unauth) and attempt to update the reply (should fail with auth error)
 */
export async function test_api_bbs_test_update_reply_by_unauthorized_user(connection: api.IConnection) {
  // 1. Register two user accounts (userA, userB)
  // For role assignment, use random UUID to represent basic member role
  const roleId: string = typia.random<string & tags.Format<"uuid">>();
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userAUsername = RandomGenerator.alphaNumeric(12);
  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: userAUsername,
      email: userAEmail,
      password: "UserAP@ssw0rd!",
      bio: "UserA bio...",
      role_id: roleId,
    },
  });
  typia.assert(userA);

  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userBUsername = RandomGenerator.alphaNumeric(12);
  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: userBUsername,
      email: userBEmail,
      password: "UserBP@ssw0rd!",
      bio: "UserB bio...",
      role_id: roleId,
    },
  });
  typia.assert(userB);

  // 2. Create a category for posts
  // (Assume first user is used for auth; random name)
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: `TestCategory_${RandomGenerator.alphaNumeric(8)}`,
      description: "A test category for reply update permission testing.",
    },
  });
  typia.assert(category);

  // 3. Login as userA (assume connection uses userA auth)
  // There is no explicit login endpoint, but connection will maintain context.
  // 4. Create a post as userA
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: `Test post by userA: ${RandomGenerator.alphabets(5)}`,
      content: "This is the body of the test post (userA).",
    },
  });
  typia.assert(post);

  // 5. Create top-level comment as userA
  const topComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Top level comment by userA.",
    },
  });
  typia.assert(topComment);

  // 6. Create reply to top comment as userA
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: topComment.id,
    body: {
      content: "Reply by userA.",
    },
  });
  typia.assert(reply);

  // 7. Switch to userB – simulate as if connection is authenticated as userB
  // This requires a new connection/session as userB.
  // For test, clone the connection and update the user context for userB.
  const connectionUserB: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
      // Assume system/API has a means to set user context via connection, typically via login
    },
    simulate: connection.simulate,
  };
  // (In real test, you'd login as userB and obtain new token, but only registration is available in SDK)
  // Attempt reply update as userB
  TestValidator.error("Non-author user cannot update reply")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connectionUserB, {
      commentId: topComment.id,
      id: reply.id,
      body: {
        content: "Malicious edit by userB!",
      },
    })
  );

  // 8. Attempt reply update without authentication (remove Authorization header)
  const connectionUnauth: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
    simulate: connection.simulate,
  };
  TestValidator.error("Anonymous cannot update reply")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connectionUnauth, {
      commentId: topComment.id,
      id: reply.id,
      body: {
        content: "Edit by anonymous should fail.",
      },
    })
  );
}

