import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test soft-deletion of a reply comment by its author.
 *
 * This test ensures that a user can soft-delete their own reply to a comment. The process involves creating a user, a category, a post within that category, a parent comment on that post, and a nested reply to that parent comment. After deleting the reply, the test must validate:
 * 1. The reply's deleted_at field is set (soft-deleted).
 * 2. The reply is still present in the database but flagged as deleted—not hard-deleted.
 * 3. The deleted reply cannot be accessed via normal user queries (e.g., cannot be loaded with standard APIs).
 *
 * Steps:
 * 1. Register a user and get their ID.
 * 2. Create a new category for the post.
 * 3. Create a new post in that category, authored by the user.
 * 4. Add a parent comment to the post by the user.
 * 5. Add a reply to the parent comment, as the same user.
 * 6. Soft-delete the reply as its author.
 * 7. (Validation) Try to fetch the reply as a regular user—it should not be accessible or should have deleted_at set.
 */
export async function test_api_bbs_test_delete_reply_with_owner_permission(connection: api.IConnection) {
  // 1. Register user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      // Using a random UUID for role assignment (in production, select from existing roles)
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: "E2E Test User"
    }
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: `e2e-test-category-${RandomGenerator.alphabets(6)}`,
      description: "Category for E2E reply soft-delete test."
    },
  });
  typia.assert(category);

  // 3. Create post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: "E2E Test Post for Reply Soft Delete",
      content: "Content of the E2E test post."
    },
  });
  typia.assert(post);

  // 4. Create parent comment
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Parent comment for reply soft-delete test."
    },
  });
  typia.assert(parentComment);

  // 5. Create reply to parent comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: "Reply to be soft-deleted."
    },
  });
  typia.assert(reply);

  // 6. Soft-delete the reply (by the author)
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: parentComment.id,
    id: reply.id,
  });

  // 7. Validation: Attempt to fetch (simulate by re-posting or by checking an expected property if possible)
  // Since the SDK does not provide a GET/retrieve API for a single reply, we assume a follow-up fetch is not available.
  // Validation strategy: add a new reply to the parent comment and ensure previous reply has deleted_at (if queried in list), or test as much as the public SDK allows.
  // This code is limited by the API surface provided: list/fetch APIs for comments/replies are not exposed. If available, would validate soft-deletion directly.
}

