import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate that only the reply owner or a moderator can delete a nested comment (reply).
 *
 * This test confirms that permission logic is enforced:
 *   - Deletion by a different user (not the reply author) is not allowed.
 *   - Unauthenticated attempts to delete a reply are also forbidden.
 *
 * Steps tested:
 * 1. Register two users: userA (who will own the reply), userB (to test failed unauthorized action).
 * 2. Create a category for posts.
 * 3. As userA, create a post in that category.
 * 4. As userA, add a base comment to the post.
 * 5. As userA, add a reply (nested comment) to the base comment.
 * 6. As userB, attempt to delete the reply - assert failure.
 * 7. Log out (remove authentication), attempt delete again unauthenticated - assert failure.
 */
export async function test_api_bbs_test_delete_reply_by_unauthorized_user(
  connection: api.IConnection,
) {
  // ----- Test Prerequisites: User/Category/Post/Comment/Reply setup -----

  // (1) Register userA (reply owner)
  // Use a random role UUID for user creation since role_id must be supplied
  const userARoleId: string = typia.random<string & tags.Format<"uuid">>();
  const userAEmail = `${RandomGenerator.alphaNumeric(8)}@usera.local`;
  const userAData = {
    username: RandomGenerator.alphaNumeric(8),
    email: userAEmail,
    password: "Password!1234",
    role_id: userARoleId,
    bio: "Owner of the reply.",
  } satisfies IBbsUsers.ICreate;
  const userA = await api.functional.bbs.users.post(connection, {
    body: userAData,
  });
  typia.assert(userA);

  // (2) Register userB (for negative test)
  const userBRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const userBEmail = `${RandomGenerator.alphaNumeric(8)}@userb.local`;
  const userBData = {
    username: RandomGenerator.alphaNumeric(8),
    email: userBEmail,
    password: "Password!5678",
    role_id: userBRoleId,
    bio: "Not the owner.",
  } satisfies IBbsUsers.ICreate;
  const userB = await api.functional.bbs.users.post(connection, {
    body: userBData,
  });
  typia.assert(userB);

  // (3) Create a new category under userA's session
  // Assume that category creation is allowed for standard users, else this should be handled by admin context in infra
  await api.functional.bbs.users.post(connection, {
    body: { ...userAData },
  });
  // (Assumption: infra connection token auto-updates to last created user purposely)

  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: `cat-${RandomGenerator.alphaNumeric(6)}`,
      description: "Test category for unauthorized delete reply test.",
    },
  });
  typia.assert(category);

  // (4) As userA, create a post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: `Title ${RandomGenerator.alphaNumeric(10)}`,
      content: "Initial post content for nested comment permission test.",
    },
  });
  typia.assert(post);

  // (5) As userA, create base comment to the post
  const baseComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "This is a base comment.",
    },
  });
  typia.assert(baseComment);

  // (6) As userA, create reply to the base comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: baseComment.id,
    body: {
      content: "This is a reply (nested comment).",
    },
  });
  typia.assert(reply);

  // -------------------------- Permission Negative Tests --------------------------

  // (7) Switch to userB context (simulate login as userB)
  await api.functional.bbs.users.post(connection, {
    body: { ...userBData },
  });
  // (Connection switches token - now userB is authenticated)

  // Attempt to delete the reply as userB -- this should fail
  TestValidator.error("Non-owner should not be allowed to delete reply")(
    async () => {
      await api.functional.bbs.comments.comments.eraseByCommentidAndId(
        connection,
        {
          commentId: baseComment.id,
          id: reply.id,
        },
      );
    },
  );

  // (8) Simulate log out by clearing connection.headers.Authorization (if infra handles state)
  if (connection.headers) delete connection.headers.Authorization;

  // Attempt to delete the reply with no authentication
  TestValidator.error("Unauthenticated user should not delete reply")(
    async () => {
      await api.functional.bbs.comments.comments.eraseByCommentidAndId(
        connection,
        {
          commentId: baseComment.id,
          id: reply.id,
        },
      );
    },
  );
}

