import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test deleting a reply that has already been soft-deleted.
 *
 * This test ensures that the API correctly handles attempts to delete a comment reply twice. It verifies that after a reply (nested comment) is created and deleted (soft-delete), attempting to delete it again results in an appropriate error (such as not found or already deleted).
 *
 * Business Workflow:
 * 1. Register a new user account for comment/reply actions.
 * 2. Create a new category providing a context for posts.
 * 3. Create a new post under the created category.
 * 4. Add a parent comment (top-level) to the post.
 * 5. Add a nested reply to the parent comment.
 * 6. Delete the reply (soft-delete it).
 * 7. Attempt to delete the same reply again and verify that an error is returned, confirming proper API protection against double-removal.
 */
export async function test_api_bbs_test_delete_reply_that_is_already_deleted(
  connection: api.IConnection,
) {
  // 1. Register new user for all actions
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      role_id: userRoleId,
      bio: RandomGenerator.paragraph()()
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create category context
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(7),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create post in category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Create parent comment on post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
