import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test deleting a reply that has already been soft-deleted.
 *
 * This test ensures the system prevents double deletion of a nested comment (reply).
 * The workflow covers user/account setup, category/post/comment hierarchy, and proper
 * error handling for repeated deletion attempts. After successful deletion (soft-delete),
 * the second request must return an error, confirming that already deleted replies
 * cannot be deleted a second time.
 *
 * Steps:
 * 1. Register a user (author for post/comment/reply).
 * 2. Create a category for nesting the post.
 * 3. Create a post assigned to the new category.
 * 4. Create a parent comment (directly under the post).
 * 5. Add a reply (nested comment) to the parent comment.
 * 6. Delete (soft-delete) the reply.
 * 7. Attempt to delete the reply again; validate error is returned.
 */
export async function test_api_bbs_test_delete_reply_that_is_already_deleted(
  connection: api.IConnection,
) {
  // 1. Register a user for all actions
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      role_id: typia.random<string & tags.Format<"uuid">>()
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create category for post nesting
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(7),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create post in the category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Add a parent (top-level) comment to the post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: { content: RandomGenerator.paragraph()() },
  });
  typia.assert(parentComment);

  // 5. Add a reply (nested comment) to the parent comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: { content: RandomGenerator.content()()() },
  });
  typia.assert(reply);

  // 6. Delete the reply (soft-delete the nested comment)
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: parentComment.id,
    id: reply.id,
  });

  // 7. Attempt to delete reply again and confirm API returns expected error (already deleted/not found)
  await TestValidator.error("should fail deleting reply that's already soft-deleted")(
    async () => {
      await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
        commentId: parentComment.id,
        id: reply.id,
      });
    },
  );
}
